    private void showModernLoader(String lang) {
        if (isFinishing() || isDestroyed()) return;
        dismissModernLoader();
        loadingDialog = new android.app.Dialog(this);
        loadingDialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);
        loadingDialog.setContentView(R.layout.dialog_modern_loading);
        loadingDialog.setCancelable(false);
        if (loadingDialog.getWindow() != null) {
            loadingDialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));
            loadingDialog.getWindow().setLayout(
                    android.view.ViewGroup.LayoutParams.MATCH_PARENT,
                    android.view.ViewGroup.LayoutParams.WRAP_CONTENT
            );
            loadingDialog.getWindow().setDimAmount(0.55f);
        }
        android.widget.TextView tvTitle = loadingDialog.findViewById(R.id.tvLoadingTitle);
        android.widget.TextView tvSubtitle = loadingDialog.findViewById(R.id.tvLoadingSubtitle);
        if ("gujarati".equalsIgnoreCase(lang)) {
            if (tvTitle != null) tvTitle.setText("\u0aaa\u0acd\u0ab0\u0ab6\u0acd\u0aa8\u0acb \u0aa4\u0ac8\u0aaf\u0abe\u0ab0 \u0aa5\u0a88 \u0ab0\u0ab9\u0acd\u0aaf\u0abe \u0a9b\u0ac7...");
            if (tvSubtitle != null) tvSubtitle.setText("\u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0\u0aa8\u0ac7 \u0aa5\u0acb\u0aa1\u0ac0 \u0ab0\u0abe\u0ab9 \u0a9c\u0ac1\u0a93");
        } else if ("hindi".equalsIgnoreCase(lang)) {
            if (tvTitle != null) tvTitle.setText("\u092a\u094d\u0930\u0936\u094d\u0928 \u0924\u0948\u092f\u093e\u0930 \u0939\u094b \u0930\u0939\u0947 \u0939\u0948\u0902...");
            if (tvSubtitle != null) tvSubtitle.setText("\u0915\u0943\u092a\u092f\u093e \u0925\u094b\u0921\u093c\u093e \u0907\u0902\u0924\u091c\u093c\u093e\u0930 \u0915\u0930\u0947\u0902");
        } else {
            if (tvTitle != null) tvTitle.setText("Preparing Questions...");
            if (tvSubtitle != null) tvSubtitle.setText("Please wait a moment");
        }
        loadingDialog.show();
    }

    private void dismissModernLoader() {
        if (loadingDialog != null && loadingDialog.isShowing()) {
            try {
                loadingDialog.dismiss();
            } catch (Exception ignored) {}
            loadingDialog = null;
        }
    }

