    @Override
    public void onCreate(Bundle bundle) {
        super.onCreate(bundle);
        getWindow().setStatusBarColor(android.graphics.Color.parseColor("#1E40AF"));
        setContentView(R.layout.task_activity_lang_select);

        //  NativeLoad();

        taskPreferenceClass = new Task_PreferenceClass(this);

        RelativeLayout native_banner_ad_container = findViewById(R.id.native_banner_ad_container);
        if (native_banner_ad_container != null) {
            Task_NativeAdUtil.loadNativeAd(native_banner_ad_container, this);
        }
        ((ImageView) findViewById(R.id.iv_back)).setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                Task_LanguageSelectActivity.this.onBackPressed();
            }
        });
        this.str_from = getIntent().getStringExtra("from");
        final SharedPreferences sharedPreferences = getSharedPreferences("ShaPreferencesChange", 0);
        this.sharedPreferences = sharedPreferences;
        this.editor = sharedPreferences.edit();
        this.iv_gujarati = (LinearLayout) findViewById(R.id.iv_gujarati);
        this.iv_hindi = (LinearLayout) findViewById(R.id.iv_hindi);
        this.iv_english = (LinearLayout) findViewById(R.id.iv_english);
        this.iv_gujarati.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                if (sharedPreferences.getBoolean(Task_LanguageSelectActivity.this.str, true)) {
                    Task_LanguageSelectActivity.this.deleteDatabase("RTODATABASE");
                    Task_LanguageSelectActivity.this.editor.putBoolean(Task_LanguageSelectActivity.this.str, true);
                    Task_LanguageSelectActivity.this.showModernLoader("gujarati");
                    Task_LanguageSelectActivity m_rtoTaskLanguageSelectActivity = Task_LanguageSelectActivity.this;
                    new Questionss_Gujarati(m_rtoTaskLanguageSelectActivity.str_from).execute(new Void[0]);
                }
            }
        });
        this.iv_hindi.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                if (sharedPreferences.getBoolean(Task_LanguageSelectActivity.this.str, true)) {
                    Task_LanguageSelectActivity.this.deleteDatabase("RTODATABASE");
                    Task_LanguageSelectActivity.this.editor.putBoolean(Task_LanguageSelectActivity.this.str, true);
                    Task_LanguageSelectActivity.this.showModernLoader("hindi");
                    Task_LanguageSelectActivity m_rtoTaskLanguageSelectActivity = Task_LanguageSelectActivity.this;
                    new Questionss_Hindi(m_rtoTaskLanguageSelectActivity.str_from).execute(new Void[0]);
                }
            }
        });
        this.iv_english.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                if (sharedPreferences.getBoolean(Task_LanguageSelectActivity.this.str, true)) {
                    Task_LanguageSelectActivity.this.deleteDatabase("RTODATABASE");
                    Task_LanguageSelectActivity.this.editor.putBoolean(Task_LanguageSelectActivity.this.str, true);
                    Task_LanguageSelectActivity.this.showModernLoader("english");
                    Task_LanguageSelectActivity m_rtoTaskLanguageSelectActivity = Task_LanguageSelectActivity.this;
                    new Questionss_English(m_rtoTaskLanguageSelectActivity.str_from).execute(new Void[0]);
                }
            }
        });
    }


