            Task_LanguageSelectActivity.this.handler.addQuestion(29, "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0ab8\u0acd\u0a95\u0ac1\u0ab2 \u0aac\u0ab8 \u0ab5\u0abf\u0aa6\u0acd\u0aaf\u0abe\u0ab0\u0acd\u0aa5\u0ac0\u0a93 \u0aa8\u0ac7 \u0a9a\u0aa2\u0ab5\u0abe \u0a85\u0aa5\u0ab5\u0abe \u0a89\u0aa4\u0abe\u0ab0\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0a8a\u0aad\u0ac0 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0aa7\u0ac0\u0aae\u0ac7\u0aa5\u0ac0 \u0a85\u0aa8\u0ac7 \u0ab8\u0abe\u0ab5\u0a9a\u0ac7\u0aa4\u0ac0 \u0aa5\u0ac0 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0acb \u0a95\u0abe\u0ab0\u0aa3\u0a95\u0ac7 \u0ab5\u0abf\u0aa6\u0acd\u0aaf\u0abe\u0ab0\u0acd\u0aa5\u0ac0 \u0a85\u0a9a\u0abe\u0aa8\u0a95 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0ac7 \u0aa4\u0ac7\u0ab5\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0aa4\u0abe \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(31, " \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0abe\u0a82\u0a95 \u0ab2\u0ac7\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1\u0aa8\u0acb \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0aac\u0aa4\u0abe\u0ab5\u0ac0 \u0ab0\u0acb\u0aa1 \u0aa8\u0ac0 \u0aa1\u0abe\u0aac\u0ac0 \u0ab8\u0abe\u0a88\u0aa1 \u0ab5\u0abe\u0ab9\u0aa8 \u0ab0\u0abe\u0a96\u0ac0\u0aa8\u0ac7 \u0ab5\u0ab3\u0abe\u0a82\u0a95 \u0ab2\u0a88\u0ab6\u0ac1\u0a82.");
            Task_LanguageSelectActivity.this.handler.addQuestion(33, "\u0ab8\u0ac0\u0a9f \u0a89\u0aaa\u0ab0 \u0ab2\u0a97\u0abe\u0ab5\u0ac7\u0ab2 \u0ab9\u0ac7\u0aa1 \u0ab0\u0ac7\u0ab8\u0acd\u0a9f \u0a95\u0a88 \u0ab0\u0ac0\u0aa4\u0ac7 \u0a89\u0aaa\u0aaf\u0acb\u0a97\u0ac0 \u0a9b\u0ac7? ", "\u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0ab5\u0a96\u0aa4\u0ac7 \u0aa1\u0acb\u0a95 \u0aa8\u0ac0 \u0a88\u0a9c\u0abe \u0aa5\u0ac0 \u0aac\u0a9a\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(35, "\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0aaa\u0abe\u0a9b\u0ab3 \u0a9c\u0acb \u0a8f\u0aae\u0acd\u0aac\u0ac1\u0ab2\u0aa8\u0acd\u0ab8 \u0aa8\u0a9c\u0ac0\u0a95 \u0a86\u0ab5\u0ac0 \u0a97\u0a88 \u0ab9\u0acb\u0aaf \u0aa4\u0acb.. ", "\u0aaa\u0acb\u0aa4\u0abe\u0aa8\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0ab0\u0acb\u0aa1 \u0aa8\u0ac0 \u0ab8\u0abe\u0a88\u0aa1 \u0aae\u0abe\u0a82 \u0ab2\u0a88\u0aa8\u0ac7 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a95\u0ab0\u0ac0 \u0a86\u0aaa\u0acb ");
            Task_LanguageSelectActivity.this.handler.addQuestion(37, "\u0ab0\u0abf\u0a95\u0acd\u0ab7\u0abe \u0a9a\u0abe\u0ab2\u0a95 \u0a9f\u0ac2\u0a82\u0a95\u0abe \u0a85\u0a82\u0aa4\u0ab0 \u0aa8\u0abe \u0aad\u0abe\u0aa1\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0a97\u0acd\u0ab0\u0abe\u0ab9\u0a95 \u0aa8\u0ac7 \u0ab2\u0a87 \u0a9c\u0ab5\u0abe\u0aa8\u0ac0 \u0aa8\u0abe \u0aaa\u0aa1\u0ac7 \u0aa4\u0acb.. ", "\u0aac\u0a82\u0aa8\u0ac7 \u0aa5\u0a87 \u0ab6\u0a95\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(39, " \u0aaf\u0ac1 \u0a9f\u0ab0\u0acd\u0aa8 \u0ab2\u0ac7\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0a95\u0a88 \u0ab0\u0ac0\u0aa4\u0ac7 \u0aa6\u0ab0\u0acd\u0ab6\u0abe\u0ab5\u0abe\u0aaf? ", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1\u0aa8\u0ac1\u0a82 \u0ab5\u0ab3\u0ab5\u0abe\u0aa8\u0ac1\u0a82 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2.");
            Task_LanguageSelectActivity.this.handler.addQuestion(41, "\u0a95\u0a88 \u0aaa\u0ab0\u0abf\u0ab8\u0acd\u0aa5\u0abf\u0aa4\u0abf \u0aae\u0abe\u0a82 \u0a93\u0ab5\u0ab0 \u0a9f\u0ac7\u0a95\u0abf\u0a82\u0a97 \u0a95\u0ab0\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7?", "\u0ab8\u0a82\u0a95\u0aa1\u0abe \u0aaa\u0ac1\u0ab2 \u0a89\u0aaa\u0ab0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(43, "\u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aae\u0acb\u0aac\u0abe\u0a88\u0ab2 \u0a89\u0aaa\u0ab0 \u0ab5\u0abe\u0aa4 \u0a95\u0ab0\u0ab5\u0ac0 \u0a9c\u0acb\u0a88\u0a8f? ", "\u0aa8\u0abe ");
            Task_LanguageSelectActivity.this.handler.addQuestion(45, "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0aae\u0abe\u0a82 \u0aac\u0ab3\u0aa4\u0aa3 ( \u0aaa\u0ac7\u0a9f\u0acd\u0ab0\u0acb\u0ab2/\u0aa1\u0ac0\u0a9d\u0ab2/\u0a97\u0ac7\u0ab8 ) \u0aad\u0ab0\u0aa4\u0abe \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0aa7\u0ac1\u0aae\u0acd\u0ab0\u0aaa\u0abe\u0aa8 \u0a95\u0ab0\u0ab5\u0ac1\u0a82 \u0aa8\u0ab9\u0abf.");
            Task_LanguageSelectActivity.this.handler.addQuestion(47, "\u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aae\u0abe\u0a9f\u0ac7 \u0ab5\u0aa7\u0ac1 \u0aae\u0abe\u0a82 \u0ab5\u0aa7\u0ac1 \u0ab8\u0acd\u0aaa\u0ac0\u0aa1.. ", "\u0aeb\u0ae6 \u0a95\u0abf\u0aae\u0ac0/\u0a95\u0ab2\u0abe\u0a95 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(49, " \u0aae\u0acb\u0aac\u0abe\u0a88\u0ab2 \u0aab\u0acb\u0aa8 \u0a95\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0ab5\u0abe\u0aaa\u0ab0\u0ac0 \u0ab6\u0a95\u0abe\u0aaf? ", "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0ab8\u0abe\u0a88\u0aa1 \u0aae\u0abe\u0a82 \u0aaa\u0abe\u0ab0\u0acd\u0a95 \u0a95\u0ab0\u0ac7\u0ab2 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7...");
            Task_LanguageSelectActivity.this.handler.addQuestion(51, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0abe \u0ab8\u0acd\u0aa5\u0ab3\u0acb \u0a8f \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7. ", "\u0ab9\u0acb\u0ab8\u0acd\u0aaa\u0abf\u0a9f\u0ab2 \u0aa8\u0abe \u0aa6\u0ab0\u0ab5\u0abe\u0a9c\u0abe \u0aaa\u0abe\u0ab8\u0ac7..");
            Task_LanguageSelectActivity.this.handler.addQuestion(53, " \u0a96\u0abe\u0aa8\u0a97\u0ac0 \u0ab5\u0abe\u0ab9\u0aa8 \u0aae\u0abe\u0a82 \u0a95\u0ac7\u0a9f\u0ab2\u0abe \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac7 \u0aac\u0ac7\u0ab8\u0abe\u0aa1\u0ac0 \u0ab6\u0a95\u0abe\u0aaf \u0aa4\u0ac7 \u0a95\u0aaf\u0abe \u0aa6\u0ab8\u0acd\u0aa4\u0abe\u0ab5\u0ac7\u0a9c \u0aae\u0abe\u0a82 \u0ab9\u0acb\u0aaf \u0a9b\u0ac7? ", "Registration Certificate \u0aae\u0abe\u0a82 \u0aa6\u0ab0\u0acd\u0ab6\u0abe\u0ab5\u0ac7\u0ab2 \u0ab8\u0a82\u0a96\u0acd\u0aaf\u0abe \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf ");
            Task_LanguageSelectActivity.this.handler.addQuestion(54, "\u0a86\u0a97\u0ab3 \u0aa8\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a93\u0ab5\u0ab0\u0a9f\u0ac7\u0a95 \u0a95\u0ab0\u0ab5\u0abe \u0aa6\u0ac7\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0aac\u0aa4\u0abe\u0ab5\u0ac7\u0ab2 \u0aa8\u0aa5\u0ac0.. ", "\u0a86\u0aaa\u0aa3\u0ac7 \u0a93\u0ab5\u0ab0\u0a9f\u0ac7\u0a95 \u0a95\u0ab0\u0ac0\u0ab6\u0ac1\u0a82 \u0aa8\u0ab9\u0abf.");
            Task_LanguageSelectActivity.this.handler.addQuestion(56, "Driver \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0aaa\u0acb\u0aa4\u0abe\u0aa8\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0a95\u0a88 \u0aac\u0abe\u0a9c\u0ac1 \u0a9a\u0ab2\u0abe\u0ab5\u0ab6\u0ac7? ", "\u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0aa8\u0ac0 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(58, "\u0a9a\u0abe\u0ab0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0aa8\u0ac0 \u0aaa\u0ac0\u0ab3\u0ac0 \u0ab2\u0abe\u0a88\u0a9f \u0aa6\u0ac7\u0a96\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0a82 \u0aaa\u0ab9\u0acb\u0a9a\u0aa4\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0acb \u0a9a\u0abe\u0ab2\u0a95.. ", "\u0aa5\u0acb\u0aad\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa7\u0ac0\u0aae\u0ac1\u0a82 \u0aaa\u0abe\u0aa1\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(60, " \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac0 \u0ab9\u0ac7\u0aa8\u0acd\u0aa1 \u0aac\u0acd\u0ab0\u0ac7\u0a95 \u0aa8\u0acb \u0a89\u0aaa\u0aaf\u0acb\u0a97 \u0a95\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0a95\u0ab0\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0a95\u0ab0\u0ab5\u0abe..");
            Task_LanguageSelectActivity.this.handler.addQuestion(62, "\u0aac\u0ac7 \u0a95\u0ab0\u0aa4\u0abe \u0ab5\u0aa7\u0ac1 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0a93 \u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aaa\u0ab0 \u0a9c\u0abe\u0aaf \u0aa4\u0acb..", "\u0a95\u0abe\u0aaf\u0aa6\u0abe \u0aa8\u0acb \u0aad\u0a82\u0a97 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(64, "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0a85\u0a82\u0aa7 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0ab8\u0aab\u0ac7\u0aa6 \u0ab2\u0abe\u0a95\u0aa1\u0ac0 \u0ab9\u0abe\u0aa5\u0aae\u0abe\u0a82 \u0aaa\u0a95\u0aa1\u0ac0 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0acb \u0a9a\u0abe\u0ab2\u0a95 \u0ab8\u0aab\u0ac7\u0aa6 \u0ab2\u0abe\u0a95\u0aa1\u0ac0 \u0aa8\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aad\u0ac1\u0a82 \u0ab0\u0abe\u0a96\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0ac1\u0a82 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0ab8\u0aae\u0a9c\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(66, "\u0ab0\u0ac0\u0ab5\u0ab0\u0acd\u0ab8 \u0a97\u0ac0\u0a85\u0ab0 \u0aae\u0abe\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.. ", "\u0a8f\u0a95 \u0aae\u0abe\u0ab0\u0acd\u0a97\u0ac0\u0aaf \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(68, " \u0aa4\u0aae\u0ac7 \u0a8f\u0ab5\u0abe \u0a9a\u0abe\u0ab0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0aaa\u0ab9\u0acb\u0a9a\u0acb \u0a9b\u0acb \u0a95\u0ac7 \u0a9c\u0acd\u0aaf\u0abe\u0a82 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0ab2\u0abe\u0a88\u0a9f \u0a95\u0ac7 \u0aaa\u0acb\u0ab2\u0ac0\u0ab8\u0aae\u0ac7\u0aa8 \u0aa8\u0aa5\u0ac0.. ", "\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0a9c\u0aae\u0aa3\u0ac0 \u0aa4\u0ab0\u0aab\u0aa5\u0ac0 \u0a9a\u0abe\u0ab0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0a86\u0ab5\u0aa4\u0abe \u0a9f\u0acd\u0ab0\u0abe\u0aab\u0abf\u0a95 \u0aa8\u0ac7 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a86\u0aaa\u0ac0 \u0aa8\u0ac7 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(70, "\u0a95\u0aaf\u0abe \u0aaa\u0acd\u0ab0\u0a95\u0abe\u0ab0 \u0aa8\u0abe \u0ab9\u0acb\u0ab0\u0acd\u0aa8 \u0aae\u0abe\u0aa8\u0acd\u0aaf \u0a9b\u0ac7? ", "\u0a88\u0ab2\u0ac7\u0a95\u0a9f\u0acd\u0ab0\u0ac0\u0a95 \u0ab9\u0acb\u0ab0\u0acd\u0aa8 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(72, "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0abe \u0ab5\u0ac0\u0aae\u0abe \u0aa8\u0ac0 \u0aae\u0ac1\u0aa6\u0aa4 ", "\u0ae7 \u0ab5\u0ab0\u0acd\u0ab7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(74, "\u0a9c\u0acd\u0aaf\u0abe\u0a82 \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7 \u0aa4\u0ac7\u0ab5\u0ac0 \u0a9c\u0a97\u0acd\u0aaf\u0abe \u0a95\u0a88? ", "\u0aab\u0ac2\u0a9f-\u0aaa\u0abe\u0aa5 \u0a89\u0aaa\u0ab0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(76, "\u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0a89\u0aaa\u0ab0 \u0aaa\u0abe\u0a9b\u0ab3 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac7 \u0aac\u0ac7\u0ab8\u0ac0 \u0a9c\u0ab5\u0ac0 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aaa\u0ab0 \u0aab\u0ac2\u0a9f \u0ab0\u0ac7\u0ab8\u0acd\u0a9f, \u0ab9\u0ac7\u0aa8\u0acd\u0aa1 \u0a97\u0acd\u0ab0\u0ac0\u0aaa \u0aa4\u0aa5\u0abe \u0ab8\u0abe\u0a88\u0aa1 \u0a97\u0abe\u0ab0\u0acd\u0aa1 \u0ab2\u0a97\u0abe\u0aa1\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ab6\u0ac7. ");
            Task_LanguageSelectActivity.this.handler.addQuestion(78, " \u0a85\u0aa8\u0acd\u0aaf \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0a93 \u0a95\u0ac7 \u0aaa\u0ac7\u0ab8\u0ac7\u0aa8\u0acd\u0a9c\u0ab0 \u0aa8\u0ac7 \u0a85\u0aa1\u0a9a\u0aa3 \u0aaa\u0aa1\u0ac7 \u0aa4\u0ac7\u0aae \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a9c\u0abe\u0ab9\u0ac7\u0ab0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0ab0\u0abe\u0a96\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ac7 \u0aa4\u0acb.. ", "\u0aac\u0a82\u0aa8\u0ac7 \u0aa5\u0a87 \u0ab6\u0a95\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(81, "\u0aa8\u0acb\u0aa8 \u0a9f\u0acd\u0ab0\u0abe\u0aa8\u0acd\u0ab8\u0acd\u0aaa\u0acb\u0a9f \u0ab5\u0abe\u0ab9\u0aa8 \u0ab8\u0abe\u0aa5\u0ac7 \u0ab0\u0abe\u0a96\u0ab5\u0abe\u0aa8\u0abe \u0aa6\u0ab8\u0acd\u0aa4\u0abe\u0ab5\u0ac7\u0a9c\u0acb.. ", "\u0a86\u0ab0.\u0ab8\u0ac0. \u0aac\u0ac1\u0a95, \u0aaa\u0ac0\u0aaf\u0ac1\u0ab8\u0ac0, \u0ab5\u0ac0\u0aae\u0abe \u0aaa\u0acd\u0ab0\u0aae\u0abe\u0aa3\u0aaa\u0aa4\u0acd\u0ab0, \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(83, " \u0aa4\u0aae\u0ac7 \u0a8f\u0ab5\u0abe \u0a9a\u0abe\u0ab0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0aaa\u0ab9\u0acb\u0a9a\u0acb \u0a9b\u0acb \u0a9c\u0acd\u0aaf\u0abe\u0a82 \u0aaa\u0ac0\u0ab3\u0ac0 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0ab2\u0abe\u0a88\u0a9f \u0a9d\u0aac\u0a95\u0abe\u0ab0\u0abe \u0aae\u0abe\u0ab0\u0ac7 \u0a9b\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa7\u0ac0\u0aae\u0ac1\u0a82 \u0a95\u0ab0\u0ac0\u0aa8\u0ac7 \u0ab8\u0ab2\u0abe\u0aae\u0aa4 \u0ab2\u0abe\u0a97\u0ac7 \u0aa4\u0ac7\u0aae \u0aa8\u0a95\u0acd\u0a95\u0ac0 \u0aa5\u0abe\u0aaf \u0aa4\u0acb \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(86, " \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0abe\u0a82\u0a95 \u0ab2\u0ac7\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0a9a\u0ab2\u0abe\u0ab5\u0aa8\u0abe\u0ab0 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0ac7? ", "\u0aaa\u0acb\u0aa4\u0abe\u0aa8\u0abe \u0a9c\u0aae\u0aa3\u0abe \u0ab9\u0abe\u0aa5 \u0aa5\u0ac0 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0a9c\u0ab5\u0abe \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0aac\u0aa4\u0abe\u0ab5\u0ab6\u0ac7. ");
            Task_LanguageSelectActivity.this.handler.addQuestion(88, " \u0aaa\u0abe\u0a9b\u0ab3 \u0aa8\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0a86\u0aaa\u0aa3\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a93\u0ab5\u0ab0 \u0a9f\u0ac7\u0a95 \u0a95\u0ab0\u0ab5\u0abe\u0aa8\u0ac1\u0a82 \u0ab6\u0ab0\u0ac1 \u0a95\u0ab0\u0acd\u0aaf\u0ac1\u0a82 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0a86\u0aaa\u0aa3\u0ac7 \u0aac\u0ac0\u0a9c\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a93\u0ab5\u0ab0 \u0a9f\u0ac7\u0a95 \u0a95\u0ab0\u0ac0\u0ab6\u0ac1\u0a82 \u0aa8\u0ab9\u0abf.");
            Task_LanguageSelectActivity.this.handler.addQuestion(90, " \u0aa8\u0abe\u0aa8\u0abe \u0ab8\u0abe\u0a88\u0aa1 \u0ab0\u0acb\u0aa1 \u0a89\u0aaa\u0ab0\u0aa5\u0ac0 \u0aae\u0ac7\u0a88\u0aa8 \u0ab0\u0acb\u0aa1 \u0a89\u0aaa\u0ab0 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0a95\u0ab0\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8\u0a9a\u0abe\u0ab2\u0a95 \u0ab6\u0ac7\u0aa8\u0ac7 \u0a85\u0a97\u0acd\u0ab0\u0aa4\u0abe \u0a86\u0aaa\u0ab6\u0ac7? ", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0aa5\u0ac0 \u0a86\u0ab5\u0aa4\u0abe \u0aa6\u0ab0\u0ac7\u0a95 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a9c\u0ab5\u0abe \u0aa6\u0ac7\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(92, "\u0aa4\u0aae\u0ac7 \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0a9a\u0aa2\u0abe\u0a82\u0aa3\u0ab5\u0abe\u0ab3\u0abe \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0abe \u0ab9\u0acb\u0ab5 \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0a9a\u0aa2\u0abe\u0a82\u0aa3 \u0a9a\u0aa2\u0aa4\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0aaa\u0ab9\u0ac7\u0ab2\u0abe \u0a9c\u0ab5\u0abe\u0aa8\u0ac0 \u0a85\u0a97\u0acd\u0ab0\u0aa4\u0abe \u0a86\u0aaa\u0ab5\u0ac0.");
            Task_LanguageSelectActivity.this.handler.addQuestion(94, "\u0ab8\u0aab\u0ac7\u0aa6 \u0ab0\u0a82\u0a97\u0aa5\u0ac0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0aa4\u0ac2\u0a9f\u0a95-\u0aa4\u0ac2\u0a9f\u0a95 \u0ab2\u0abe\u0a88\u0aa8 \u0a9a\u0ac0\u0aa4\u0ab0\u0ac7\u0ab2\u0ac0 \u0ab9\u0acb\u0aaf \u0aa4\u0acb \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0a9c\u0ab0\u0ac2\u0ab0 \u0aaa\u0aa1\u0ac7 \u0aa4\u0acb track \u0aac\u0aa6\u0ab2\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(96, "\u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0aaa\u0ab0 \u0aaa\u0ac0\u0ab3\u0abe \u0ab0\u0a82\u0a97 \u0aa8\u0ac0 \u0ab2\u0abe\u0a88\u0a9f \u0a9d\u0aac\u0ac1\u0a95-\u0a9d\u0aac\u0ac1\u0a95 \u0aa5\u0abe\u0aaf \u0a9b\u0ac7 \u0aa4\u0ac7\u0aa8\u0acb \u0a85\u0ab0\u0acd\u0aa5.. ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac0 \u0a97\u0aa4\u0abf \u0a93\u0a9b\u0ac0 \u0a95\u0ab0\u0acb \u0a85\u0aa8\u0ac7 \u0ab8\u0ab2\u0abe\u0aae\u0aa4\u0ac0 \u0aaa\u0ac2\u0ab0\u0acd\u0ab5\u0a95 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(98, "\u0ab5\u0ab0\u0ab8\u0abe\u0aa6 \u0aae\u0abe\u0a82 \u0aac\u0acd\u0ab0\u0ac7\u0a95 \u0ab2\u0a97\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0ab8\u0acd\u0a9f\u0acb\u0aaa\u0ac0\u0a82\u0a97 \u0aa1\u0abf\u0ab8\u0acd\u0a9f\u0aa8\u0acd\u0ab8 \u0a89\u0aaa\u0ab0 \u0ab6\u0ac1\u0a82 \u0a85\u0ab8\u0ab0 \u0aaa\u0aa1\u0ac7 \u0a9b\u0ac7? ", "\u0ab8\u0acd\u0a9f\u0acb\u0aaa\u0ac0\u0a82\u0a97 \u0aa1\u0abf\u0ab8\u0acd\u0a9f\u0aa8\u0acd\u0ab8 \u0ab5\u0aa7\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(100, " \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0a9a\u0abe\u0ab2\u0a95\u0ac7 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0a95\u0aaf\u0abe \u0ab8\u0acd\u0ab5\u0ab0\u0ac2\u0aaa\u0ac7 \u0ab8\u0abe\u0aa5\u0ac7 \u0ab0\u0abe\u0a96\u0ab5\u0ac1\u0a82 \u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a9b\u0ac7? ", "\u0a85\u0ab8\u0ab2 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8");
            Task_LanguageSelectActivity.this.handler.addQuestion(102, "\u0a95\u0acb\u0a88 \u0a9c\u0a97\u0acd\u0aaf\u0abe \u0a8f \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0a95\u0abe\u0ab0\u0aa8\u0ac7 \u0ab0\u0ac0\u0ab5\u0ab0\u0acd\u0ab8 \u0a95\u0ab0\u0ab5\u0ac0 \u0ab8\u0ab2\u0abe\u0aae\u0aa4 \u0aa8\u0aa5\u0ac0. \u0aa4\u0aae\u0abe\u0ab0\u0ac7.. ", "\u0a86\u0a97\u0ab3 \u0a9c\u0ab5\u0ac1\u0a82 \u0a85\u0aa8\u0ac7 \u0ab0\u0ac0\u0ab5\u0ab0\u0acd\u0ab8 \u0a95\u0ab0\u0ab5\u0abe \u0a85\u0aa8\u0ac1\u0a95\u0ac1\u0ab3 \u0a9c\u0a97\u0acd\u0aaf\u0abe \u0ab6\u0acb\u0aa7\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(104, " \u0ab0\u0abe\u0aa4\u0acd\u0ab0\u0ac0 \u0aa6\u0ab0\u0aae\u0abf\u0aaf\u0abe\u0aa8 \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0ab0\u0acb\u0aa1 \u0aa8\u0ac0 \u0ab8\u0abe\u0a88\u0aa1 \u0aae\u0abe\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa5\u0acb\u0aad\u0abe\u0ab5\u0acb \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0ab2\u0abe\u0a88\u0a9f \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac0 \u0a9a\u0abe\u0ab2\u0ac1 \u0a95\u0ab0\u0ab5\u0ac0 \u0a9c\u0acb\u0a88\u0a8f.");
            Task_LanguageSelectActivity.this.handler.addQuestion(106, " \u0aa4\u0aae\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac0 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1\u0a8f \u0aa5\u0ac0 \u0a93\u0ab5\u0ab0 \u0a9f\u0ac7\u0a95 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acb \u0a9b\u0acb \u0a9c\u0acb - ", "\u0a86\u0a97\u0ab3 \u0aa8\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0aac\u0aa4\u0abe\u0ab5\u0ac0\u0aa8\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0abe\u0a96\u0ac7..");
            Task_LanguageSelectActivity.this.handler.addQuestion(108, "\u0aa4\u0aae\u0ac7 \u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aa8\u0ac1\u0a82 \u0ab2\u0aa8\u0ab0\u0acd\u0ab8 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa7\u0ab0\u0abe\u0ab5\u0aa4\u0abe \u0ab9\u0acb\u0aaf \u0aa4\u0acb.. ", "\u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aa8\u0ac1\u0a82 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa7\u0ab0\u0abe\u0ab5\u0aa8\u0abe\u0ab0 \u0a87\u0aa8\u0ab8\u0acd\u0a9f\u0acd\u0ab0\u0a95\u0a9f\u0ab0 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0ab8\u0abe\u0aa5\u0ac7 \u0ab9\u0ab6\u0ac7 \u0aa4\u0acb \u0a9c \u0aa4\u0aae\u0ac7 \u0ab9\u0abe\u0a95\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(110, "\u0aa8\u0ac0\u0a9a\u0ac7\u0aa8\u0abe \u0ab8\u0a82\u0a9c\u0acb\u0a97\u0acb \u0aae\u0abe\u0a82 \u0a93\u0ab5\u0ab0-\u0a9f\u0ac7\u0a95\u0abf\u0a82\u0a97 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7. ", "\u0a85\u0aa8\u0acd\u0aaf \u0a9f\u0acd\u0ab0\u0abe\u0aab\u0abf\u0a95 \u0aa8\u0ac7 \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0aad\u0aaf \u0a89\u0aad\u0acb \u0aa5\u0abe\u0aaf \u0aa4\u0ac7\u0ab5\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0aa4\u0abe \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(112, "\u0a96\u0abe\u0aa8\u0a97\u0ac0 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac0 \u0aa8\u0a82\u0aac\u0ab0 \u0aaa\u0acd\u0ab2\u0ac7\u0a9f \u0aa8\u0acb \u0ab0\u0a82\u0a97.. ", "\u0ab8\u0aab\u0ac7\u0aa6 \u0ab0\u0a82\u0a97 \u0aa8\u0ac0 \u0aaa\u0acd\u0ab2\u0ac7\u0a9f \u0a89\u0aaa\u0ab0 \u0a95\u0abe\u0ab3\u0abe \u0a85\u0a95\u0acd\u0ab7\u0ab0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(114, " \u0a95\u0acb\u0aae\u0ab0\u0acd\u0ab6\u0ac0\u0aaf\u0ab2 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0ac1\u0a82 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0ab2\u0ac7\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a89\u0a82\u0aae\u0ab0 ", "\u0ae8\u0ae6 \u0ab5\u0ab0\u0acd\u0ab7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(116, " \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0a95\u0ab0\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7..", "\u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0aac\u0acd\u0ab0\u0ac7\u0a95 \u0ab2\u0a97\u0abe\u0aa1\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(119, "\u0ab0\u0acb\u0aa1 \u0a89\u0aaa\u0ab0 \u0a9d\u0ac7\u0aac\u0acd\u0ab0\u0abe \u0ab2\u0abe\u0a87\u0aa8\u0acd\u0ab8 \u0ab6\u0ac1\u0a82 \u0aa6\u0ab0\u0acd\u0ab6\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0 \u0aa8\u0ac7 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(121, "\u0aa4\u0aae\u0ac7 \u0ab8\u0abe\u0a82\u0a95\u0ab3\u0abe \u0aa8\u0abe\u0ab3\u0abe \u0aaa\u0abe\u0ab8\u0ac7 \u0aaa\u0ab9\u0acb\u0a9a\u0acb \u0a9b\u0acb, \u0ab8\u0abe\u0aae\u0ac7\u0aa5\u0ac0 \u0aa8\u0abe\u0ab3\u0abe \u0aae\u0abe\u0a82 \u0aac\u0ac0\u0a9c\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6\u0ac7 \u0a9b\u0ac7, \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb?", "\u0ab8\u0abe\u0aae\u0ac7\u0aa8\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0ab8\u0abe\u0ab0 \u0aa5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0a82 \u0ab8\u0ac1\u0aa7\u0ac0 \u0aa5\u0acb\u0aad\u0ac0 \u0aa4\u0acd\u0aaf\u0abe\u0ab0 \u0aac\u0abe\u0aa6 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(123, "\u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0\u0a93 \u0aae\u0abe\u0a9f\u0ac7\u0aa8\u0abe \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 \u0a89\u0aaa\u0ab0 \u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ab5\u0abe \u0a89\u0aad\u0abe \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aad\u0ac1\u0a82 \u0ab0\u0abe\u0a96\u0ac0 \u0aa6\u0a88 \u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0\u0a93 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ac0 \u0ab2\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0a82 \u0ab8\u0ac1\u0aa7\u0ac0 \u0aa5\u0acb\u0aad\u0ac0 \u0aaa\u0a9b\u0ac0 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(125, " \u0aa7\u0ac1\u0aae\u0acd\u0aae\u0ab8 \u0ab2\u0ac7\u0aae\u0acd\u0aaa (\u0aab\u0acb\u0a97 \u0ab2\u0ac7\u0aae\u0acd\u0aaa) \u0aa8\u0acb \u0a89\u0aaa\u0aaf\u0acb\u0a97 \u0a95\u0ab0\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ac7 \u0a9b\u0ac7... ", "\u0ab5\u0abe\u0aa4\u0abe\u0ab5\u0ab0\u0aa3 \u0aae\u0abe\u0a82 \u0aa7\u0ac1\u0aae\u0acd\u0aae\u0ab8 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7..");
            Task_LanguageSelectActivity.this.handler.addQuestion(126, "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0acb \u0a9a\u0abe\u0ab2\u0a95 \u0a93\u0ab5\u0ab0 \u0a9f\u0ac7\u0a95 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0ac7 \u0a9b\u0ac7.. ", "\u0a86\u0a97\u0ab3 \u0a9c\u0aa4\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0acb \u0a9a\u0abe\u0ab2\u0a95 \u0a93\u0ab5\u0ab0 \u0a9f\u0ac7\u0a88\u0a95 \u0a95\u0ab0\u0ab5\u0abe \u0aa6\u0ac7\u0ab5\u0abe\u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(129, " \u0ab8\u0abe\u0aae\u0ac7\u0aa5\u0ac0 \u0a86\u0ab5\u0aa4\u0abe \u0ab5\u0abe\u0ab9\u0aa8\u0aa8\u0ac7 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0a95\u0a88 \u0ab8\u0abe\u0a88\u0aa1 \u0aa5\u0ac0 \u0aaa\u0ab8\u0abe\u0ab0 \u0aa5\u0ab5\u0abe \u0aa6\u0ac7\u0ab6\u0acb? ", "\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1\u0aa5\u0ac0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(132, " \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95 \u0aaa\u0acb\u0aa4\u0abe\u0aa8\u0acb \u0a9c\u0aae\u0aa3\u0acb \u0ab9\u0abe\u0aa5 \u0aac\u0ab9\u0abe\u0ab0 \u0a95\u0abe\u0aa2\u0ac0 \u0ab9\u0aa5\u0ac7\u0ab3\u0ac0 \u0aa8\u0ac0\u0a9a\u0ac7 \u0aa8\u0ac0 \u0aa4\u0ab0\u0aab \u0ab0\u0abe\u0a96\u0ac0 \u0ab9\u0abe\u0aa5 \u0a98\u0aa3\u0ac0\u0ab5\u0abe\u0ab0 \u0a89\u0aaa\u0ab0 \u0aa8\u0ac0\u0a9a\u0ac7 \u0a95\u0ab0\u0ac7 \u0a9b\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 ? ", "\u0aa4\u0ac7 \u0aaa\u0acb\u0aa4\u0abe\u0aa8\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa7\u0ac0\u0aae\u0ac1\u0a82 \u0a95\u0ab0\u0ac0 \u0ab0\u0ab9\u0acd\u0aaf\u0acb \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(134, " \u0a93\u0ab5\u0ab0 \u0a9f\u0ac7\u0a95\u0abf\u0a82\u0a97 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7? ", "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0a86\u0a97\u0ab3 \u0aa8\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0aac\u0ab0\u0abe\u0aac\u0ab0 \u0aa8 \u0aa6\u0ac7\u0a96\u0abe\u0aa4\u0acb \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(136, "\u0a95\u0aaf\u0abe \u0aaa\u0acd\u0ab0\u0a95\u0abe\u0ab0 \u0aa8\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0a9a\u0abe\u0ab2\u0a95\u0ac7 \u0a97\u0aa3\u0ab5\u0ac7\u0ab6 \u0aaa\u0ab9\u0ac7\u0ab0\u0ab5\u0acb \u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a9b\u0ac7? ", "\u0aa4\u0aae\u0abe\u0aae \u0a95\u0acb\u0aae\u0ab0\u0acd\u0ab6\u0abf\u0a85\u0ab2 \u0ab5\u0abe\u0ab9\u0aa8\u0acb");
            Task_LanguageSelectActivity.this.handler.addQuestion(138, " \u0aec\u0aeb \u0a95\u0abf.\u0aae\u0ac0. \u0a95\u0ab0\u0aa4\u0abe \u0ab5\u0aa7\u0ac1 \u0ab8\u0acd\u0aaa\u0ac0\u0aa1\u0ac7 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0abe \u0aae\u0abe\u0aa8\u0acd\u0aaf \u0ab5\u0abe\u0ab9\u0aa8 \u0aab\u0a95\u0acd\u0aa4 ", "\u0aae\u0acb\u0a9f\u0ab0 \u0a95\u0abe\u0ab0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(140, "\u0ab5\u0abe\u0ab9\u0aa8 \u0a97\u0aa4\u0abf \u0aae\u0abe\u0a82 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8\u0aae\u0abe\u0a82\u0aa5\u0ac0 \u0a89\u0aa4\u0ab0\u0ab5\u0ac1\u0a82 \u0a95\u0ac7 \u0a9a\u0aa2\u0ab5\u0ac1\u0a82 ", "\u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0ab5\u0abe\u0ab9\u0aa8 \u0aae\u0abe\u0a82 \u0aae\u0abe\u0aa8\u0acd\u0aaf \u0aa8\u0aa5\u0ac0.");
            Task_LanguageSelectActivity.this.handler.addQuestion(142, "\u0aa4\u0aae\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0acb \u0aab\u0acd\u0aaf\u0ac1\u0a85\u0ab2 \u0ab5\u0aaa\u0ab0\u0abe\u0ab6 \u0a98\u0a9f\u0abe\u0aa1\u0ab5\u0abe.. ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac1\u0a82 \u0aaf\u0acb\u0a97\u0acd\u0aaf \u0a9f\u0acd\u0aaf\u0ac1\u0aa8\u0ac0\u0a82\u0a97 \u0a95\u0ab0\u0abe\u0ab5\u0ab6\u0acb. ");
            Task_LanguageSelectActivity.this.handler.addQuestion(144, "\u0aaa\u0abe\u0a9b\u0ab3 \u0aa8\u0ac1\u0a82 \u0aa6\u0acd\u0ab0\u0ab6\u0acd\u0aaf \u0a9c\u0acb\u0ab5\u0abe\u0aa8\u0acb \u0a85\u0ab0\u0ac0\u0ab8\u0acb \u0ab6\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0ab5\u0aaa\u0ab0\u0abe\u0aaf \u0a9b\u0ac7? ", "\u0aaa\u0abe\u0a9b\u0ab3 \u0aa5\u0ac0 \u0a86\u0ab5\u0aa4\u0abe \u0ab5\u0abe\u0ab9\u0aa8\u0acb \u0a9c\u0acb\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(146, " \u0aae\u0acb\u0a9f\u0ab0 \u0a95\u0abe\u0ab0 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0ab5\u0aa7\u0ac1 \u0aae\u0abe\u0a82 \u0ab5\u0aa7\u0ac1 \u0a97\u0aa4\u0abf \u0aae\u0ab0\u0acd\u0aaf\u0abe\u0aa6\u0abe \u0a95\u0ac7\u0a9f\u0ab2\u0ac0 \u0a9b\u0ac7? ", "\u0a95\u0acb\u0a88 \u0aae\u0ab0\u0acd\u0aaf\u0abe\u0aa6\u0abe \u0aa8\u0aa5\u0ac0.");
            Task_LanguageSelectActivity.this.handler.addQuestion(150, " \u0a95\u0abe\u0aaf\u0aa6\u0abe \u0aae\u0ac1\u0a9c\u0aac \u0aa6\u0acd\u0ab5\u0abf\u0a9a\u0a95\u0acd\u0ab0\u0abf \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa8\u0abe\u0ab0 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf ", "\u0ab9\u0ac7\u0ab2\u0acd\u0aae\u0ac7\u0a9f \u0aaa\u0ab9\u0ac7\u0ab0\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(154, " \u0a9c\u0ab0\u0ac2\u0ab0\u0abf\u0aaf\u0abe\u0aa4 \u0ab5\u0a97\u0ab0 \u0ab9\u0acb\u0ab0\u0acd\u0aa8 \u0aa8\u0acb \u0ab5\u0abe\u0ab0\u0a82\u0ab5\u0abe\u0ab0 \u0a89\u0aaa\u0aaf\u0acb\u0a97 \u0a97\u0ac1\u0aa8\u0acd\u0ab9\u0acb \u0aac\u0aa8\u0ac7 \u0a9b\u0ac7. ", "\u0ab9\u0abe ");
            Task_LanguageSelectActivity.this.handler.addQuestion(155, "\u0aaa\u0ac0.\u0aaf\u0ac1.\u0ab8\u0ac0. \u0aa8\u0ac0 \u0aae\u0ac1\u0aa6\u0aa4 \u0a95\u0ac7\u0a9f\u0ab2\u0ac0 \u0a9b\u0ac7? ", "\u0aec \u0aae\u0ab9\u0abf\u0aa8\u0abe ");
            Task_LanguageSelectActivity.this.handler.addQuestion(156, "\u0a9f\u0acd\u0ab0\u0abe\u0aab\u0abf\u0a95 \u0a9c\u0a82\u0a95\u0ab6\u0aa8 \u0a89\u0aaa\u0ab0 \u0ab2\u0ac0\u0ab2\u0ac0 \u0ab2\u0abe\u0a88\u0a9f \u0aaa\u0a9b\u0ac0 \u0a95\u0a88 \u0ab2\u0abe\u0a88\u0a9f \u0aa5\u0ab6\u0ac7? ", "\u0aaa\u0ac0\u0ab3\u0ac0");
            Task_LanguageSelectActivity.this.handler.addQuestion(157, " \u0aad\u0abe\u0aa1\u0ac7\u0aa5\u0ac0 \u0aab\u0ab0\u0aa4\u0abe \u0ab5\u0abe\u0ab9\u0aa8\u0aa8\u0ac0 \u0aa8\u0a82\u0aac\u0ab0 \u0aaa\u0acd\u0ab2\u0ac7\u0a9f \u0a95\u0aaf\u0abe \u0a95\u0ab2\u0ab0 \u0aa8\u0ac0 \u0ab9\u0acb\u0aaf \u0a9b\u0ac7? ", "\u0aaa\u0ac0\u0ab3\u0ac0 \u0aaa\u0acd\u0ab2\u0ac7\u0a9f \u0a89\u0aaa\u0ab0 \u0a95\u0abe\u0ab3\u0abe \u0a85\u0a95\u0acd\u0ab7\u0ab0\u0acb ");
            Task_LanguageSelectActivity.this.handler.addQuestion(158, "\u0aa8\u0ab6\u0acb \u0a95\u0ab0\u0ac0\u0aa8\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0ac1\u0a82.. ", "\u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0ab5\u0abe\u0ab9\u0aa8 \u0aae\u0abe\u0a82 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(159, "\u0ab5\u0aa7\u0ac1 \u0aae\u0abe\u0a82 \u0ab5\u0aa7\u0ac1 \u0aeb\u0ae6 \u0a95\u0abf\u0aae\u0ac0/\u0a95\u0ab2\u0abe\u0a95 \u0aa8\u0ac0 \u0a9d\u0aa1\u0aaa\u0ac7 \u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0a9a\u0ab2\u0abe\u0ab5\u0ac0 \u0ab6\u0a95\u0abe\u0aaf.. ", "\u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0ab8\u0aae\u0aaf\u0ac7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(160, "\u0ab0\u0ac0\u0ab5\u0ab0\u0acd\u0ab8 \u0ab2\u0abe\u0a88\u0a9f \u0aa8\u0acb \u0ab0\u0a82\u0a97 \u0a95\u0ac7\u0ab5\u0acb \u0ab9\u0acb\u0aaf \u0a9b\u0ac7? ", "\u0ab8\u0aab\u0ac7\u0aa6 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(161, "\u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aa4\u0aae\u0ac7 \u0ab6\u0ac7\u0aa8\u0ac1\u0a82 \u0aa7\u0acd\u0aaf\u0abe\u0aa8 \u0ab0\u0abe\u0a96\u0ab6\u0acb? ", "\u0aac\u0a82\u0aa8\u0ac7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(162, "\u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa8\u0ac0 \u0aae\u0ac1\u0aa6\u0aa4 \u0aaa\u0ac2\u0ab0\u0ac0 \u0aa5\u0aaf\u0abe \u0aac\u0abe\u0aa6 \u0a95\u0ac7\u0a9f\u0ab2\u0abe \u0ab8\u0aae\u0aaf \u0ab8\u0ac1\u0aa7\u0ac0 \u0a9a\u0abe\u0ab2\u0a95 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ac0 \u0ab6\u0a95\u0ac7? ", "\u0ae9\u0ae6 \u0aa6\u0abf\u0ab5\u0ab8");
            Task_LanguageSelectActivity.this.handler.addQuestion(163, "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0ab2\u0aaa\u0ab8\u0aa3\u0acb \u0a9b\u0ac7 \u0aa4\u0ac7\u0ab5\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0aa6\u0ac7\u0a96\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95.. ", "\u0a97\u0ac0\u0aaf\u0ab0 \u0aac\u0aa6\u0ab2\u0ac0 \u0aa8\u0ac7 \u0a97\u0aa4\u0abf \u0aa7\u0ac0\u0aae\u0ac0 \u0a95\u0ab0\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(164, " \u0a95\u0abe\u0aaf\u0aa6\u0abe \u0aae\u0ac1\u0a9c\u0aac \u0aae\u0acb\u0a9f\u0ab0 \u0a95\u0abe\u0ab0 \u0a9a\u0ab2\u0abe\u0ab5\u0aa8\u0abe\u0ab0 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf.. ", "\u0ab8\u0ac0\u0a9f \u0aac\u0ac7\u0ab2\u0acd\u0a9f \u0aac\u0abe\u0a82\u0aa7\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(165, "\u0a95\u0abe\u0ab0 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0ac1\u0a82 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0ab2\u0ac7\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a89\u0a82\u0aae\u0ab0 ", "\u0ae7\u0aee \u0ab5\u0ab0\u0acd\u0ab7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(166, "\u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0abe \u0a95\u0abf\u0ab8\u0acd\u0ab8\u0abe\u0aae\u0abe\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa7\u0ab0\u0abe\u0ab5\u0aa4\u0abe \u0aa8\u0aa5\u0ac0. ", "\u0a87\u0aa8\u0acd\u0ab8\u0acd\u0aaf\u0acb\u0ab0\u0aa8\u0acd\u0ab8 \u0a95\u0a82\u0aaa\u0aa8\u0ac0 \u0ab8\u0a82\u0aaa\u0ac2\u0ab0\u0acd\u0aa3 \u0a95\u0ab2\u0ac7\u0a88\u0aae \u0aa8\u0abe\u0aae\u0a82\u0a9c\u0ac2\u0ab0 \u0a95\u0ab0\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(167, "\u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0a9a\u0abe\u0ab2\u0a95 \u0a95\u0a88 \u0ab0\u0ac0\u0aa4\u0ac7 \u0aa5\u0abe\u0a95 \u0a89\u0aa4\u0abe\u0ab0\u0ab6\u0ac7? ", "\u0aa6\u0ab0 \u0aac\u0ac7 \u0a95\u0ab2\u0abe\u0a95\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aad\u0ac1\u0a82 \u0ab0\u0abe\u0a96\u0ac0 \u0a86\u0ab0\u0abe\u0aae \u0a95\u0ab0\u0ac0\u0aa8\u0ac7 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(168, "\u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aae\u0acb\u0aac\u0abe\u0a88\u0ab2 \u0aab\u0acb\u0aa8 \u0aa8\u0acb \u0a89\u0aaa\u0aaf\u0acb\u0a97 \u0a95\u0ab0\u0ab5\u0abe\u0aa5\u0ac0 ", "\u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0aa4\u0abe\u0a93 \u0ab5\u0aa7\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(169, "\u0aa2\u0acb\u0ab3\u0abe\u0ab5\u0ab5\u0abe\u0ab3\u0abe \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0\u0aa5\u0ac0 \u0aa8\u0ac0\u0a9a\u0ac7 \u0a89\u0aa4\u0ab0\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb?", "\u0aac\u0a82\u0aa8\u0ac7 \u0a9f\u0abe\u0ab3\u0ab6\u0acb. ");
            Task_LanguageSelectActivity.this.handler.addQuestion(170, "\u0ab0\u0abe\u0aa4\u0acd\u0ab0\u0ac0 \u0aa8\u0abe \u0ab8\u0aae\u0aaf\u0ac7 \u0aa4\u0aae\u0abe\u0ab0\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0a95\u0ab0\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0aac\u0a82\u0aa8\u0ac7 \u0a95\u0ab0\u0ac0\u0ab6\u0ac1\u0a82.");
            Task_LanguageSelectActivity.this.handler.addQuestion(171, " \u0ab2\u0abe\u0ab2 \u0a85\u0aa8\u0ac7 \u0ab8\u0aab\u0ac7\u0aa6 \u0aaa\u0a9f\u0acd\u0a9f\u0abe\u0ab5\u0abe\u0ab3\u0ac0 \u0ab0\u0abf\u0aac\u0aa8 \u0aa5\u0ac0 \u0a97\u0abe\u0ab0\u0acd\u0aa1 \u0a95\u0ab0\u0ac7\u0ab2\u0ac0 \u0a9c\u0a97\u0acd\u0aaf\u0abe \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab0\u0acb\u0aa1 \u0aa8\u0ac1\u0a82 \u0ab0\u0ac0\u0aaa\u0ac7\u0ab0\u0ac0\u0a82\u0a97 \u0a95\u0abe\u0aae \u0a9a\u0abe\u0ab2\u0ac1 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(172, "\u0a86\u0ab0.\u0a9f\u0ac0.\u0a93. \u0aa6\u0acd\u0ab5\u0abe\u0ab0\u0abe \u0a86\u0aaa\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ac7\u0ab2 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0a95\u0acd\u0aaf\u0abe\u0a82 \u0aae\u0abe\u0aa8\u0acd\u0aaf \u0a9b\u0ac7? ", "\u0ab8\u0aae\u0a97\u0acd\u0ab0 \u0aa6\u0ac7\u0ab6 \u0aae\u0abe\u0a82 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(173, "\u0ab0\u0acb\u0aa1 \u0ab8\u0abe\u0a88\u0aa8 \u0aae\u0abe\u0a82 \u0ab5\u0aaa\u0ab0\u0abe\u0aa4\u0ac0 \u0ab8\u0acd\u0a9f\u0acb\u0aaa \u0ab2\u0abe\u0a88\u0aa8\u0aae\u0abe\u0a82 \u0a95\u0aaf\u0acb \u0a95\u0ab2\u0ab0 \u0ab9\u0acb\u0aaf \u0a9b\u0ac7? ", "\u0ab8\u0aab\u0ac7\u0aa6");
            Task_LanguageSelectActivity.this.handler.addQuestion(174, " \u0aa6\u0acd\u0ab5\u0abf\u0a9a\u0a95\u0acd\u0ab0\u0ac0 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aae\u0ab9\u0abf\u0ab2\u0abe\u0a93 \u0aae\u0abe\u0a9f\u0ac7 \u0ab9\u0ac7\u0ab2\u0acd\u0aae\u0ac7\u0a9f \u0aaa\u0ab9\u0ac7\u0ab0\u0ab5\u0ac0.. ", "\u0a95\u0abe\u0aaf\u0aa6\u0abe \u0aa5\u0ac0 \u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(175, " \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0abe \u0a95\u0abf\u0ab8\u0acd\u0ab8\u0abe\u0aae\u0abe\u0a82 \u0aaa\u0ac7\u0ab8\u0ac7\u0aa8\u0acd\u0a9c\u0ab0 \u0aa8\u0abe \u0aac\u0a9a\u0abe\u0ab5 \u0aae\u0abe\u0a9f\u0ac7 \u0ab8\u0ab2\u0abe\u0aae\u0aa4\u0ac0 \u0aa8\u0ac1\u0a82 \u0a95\u0aaf\u0ac1\u0a82 \u0ab8\u0abe\u0aa7\u0aa8 \u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a9b\u0ac7? ", "\u0ab8\u0ac0\u0a9f \u0aac\u0ac7\u0ab2\u0acd\u0a9f ");
            Task_LanguageSelectActivity.this.handler.addQuestion(176, "\u0ab2\u0abe\u0a82\u0aac\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac0 \u0aaa\u0abe\u0a9a\u0ab3 \u0ab9\u0abe\u0a82\u0a95\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0aa4\u0aae\u0ac7. ", "\u0a98\u0aa3\u0ac1\u0a82 \u0ab5\u0aa7\u0abe\u0ab0\u0ac7 \u0a85\u0a82\u0aa4\u0ab0 \u0ab0\u0abe\u0a96\u0ab6\u0acb \u0a9c\u0ac7\u0aa5\u0ac0 \u0a86\u0a97\u0ab3 \u0aa8\u0abe \u0a9f\u0acd\u0ab0\u0abe\u0aab\u0abf\u0a95 \u0aa8\u0ac7 \u0ab8\u0abe\u0ab0\u0ac0 \u0ab0\u0ac0\u0aa4\u0ac7 \u0a9c\u0acb\u0a88 \u0ab6\u0a95\u0abe\u0aaf.");
            Task_LanguageSelectActivity.this.handler.addQuestion(177, "\u0ab0\u0acb\u0aa1 \u0aa8\u0ac0 \u0aae\u0aa7\u0acd\u0aaf \u0aae\u0abe\u0a82 \u0aa6\u0acb\u0ab0\u0ac7\u0ab2 \u0aaa\u0ac0\u0ab3\u0abe \u0ab0\u0a82\u0a97 \u0aa8\u0abe \u0ab8\u0ab3\u0a82\u0a97 \u0aaa\u0a9f\u0acd\u0a9f\u0abe \u0a8f\u0a9f\u0ab2\u0ac7.. ", "\u0aaa\u0ac0\u0ab3\u0ac0 \u0ab2\u0abe\u0a88\u0aa8 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(178, " \u0aae\u0abe\u0aa8\u0acd\u0aaf \u0ab8\u0ac7\u0aa8\u0acd\u0a9f\u0ab0 \u0aae\u0abe\u0a82\u0aa5\u0ac0 \u0aa4\u0aae\u0ac7 \u0a8f\u0ab2\u0aaa\u0ac0\u0a9c\u0ac0/\u0ab8\u0ac0\u0a8f\u0aa8\u0a9c\u0ac0 \u0a95\u0ac0\u0a9f \u0aab\u0ac0\u0a9f \u0a95\u0ab0\u0abe\u0ab5\u0ac0 \u0a9b\u0ac7. \u0a86\u0ab0\u0a9f\u0ac0\u0a93 \u0aae\u0abe\u0a82\u0aa5\u0ac0 \u0aa4\u0ac7\u0aa8\u0ac0 \u0aa8\u0acb\u0a82\u0aa7\u0aa3\u0ac0 \u0a95\u0ab0\u0abe\u0ab5\u0ab5\u0ac0 \u0aab\u0ab0\u0a9c\u0ac0\u0a86\u0aa4 \u0a9b\u0ac7? ", "\u0ab9\u0abe ");
            Task_LanguageSelectActivity.this.handler.addQuestion(179, " \u0a86\u0ab2\u0acd\u0a95\u0acb\u0ab9\u0acb\u0ab2 \u0aa8\u0ac1\u0a82 \u0ab8\u0ac7\u0ab5\u0aa8 \u0a95\u0abe\u0ab0\u0acd\u0aaf \u0aac\u0abe\u0aa6 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0abe\u0aa5\u0ac0... ", "\u0aac\u0a82\u0aa8\u0ac7 \u0aa5\u0a87 \u0ab6\u0a95\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(180, " \u0aaa\u0ac1\u0a96\u0acd\u0aa4 \u0ab5\u0aaf\u0aa8\u0abe \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0abe \u0ab9\u0ac3\u0aa6\u0aaf\u0aa8\u0abe \u0aa7\u0aac\u0a95\u0abe\u0ab0\u0abe \u0ab8\u0abe\u0aae\u0abe\u0aa8\u0acd\u0aaf \u0ab0\u0ac0\u0aa4\u0ac7 \u0a95\u0ac7\u0a9f\u0ab2\u0abe \u0ab9\u0acb\u0aaf \u0a9b\u0ac7? ", "\u0aed\u0ae6/\u0aae\u0abf\u0aa8\u0ac0\u0a9f ");
            Task_LanguageSelectActivity.this.handler.addQuestion(181, " \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0a95\u0abe\u0ab0 \u0aae\u0abe\u0a82 \u0a9a\u0abe\u0a88\u0ab2\u0acd\u0aa1 \u0ab2\u0acb\u0a95 \u0a9a\u0abe\u0ab2\u0ac1 \u0a95\u0ab0\u0ac7\u0ab2 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7.. ", "\u0aa6\u0ab0\u0ab5\u0abe\u0a9c\u0acb \u0aac\u0ab9\u0abe\u0ab0 \u0aa8\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0aa5\u0ac0 \u0a96\u0acb\u0ab2\u0ac0 \u0ab6\u0a95\u0abe\u0aaf ");
            Task_LanguageSelectActivity.this.handler.addQuestion(182, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0abe \u0a95\u0abf\u0ab8\u0acd\u0ab8\u0abe\u0aae\u0abe\u0a82 \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7. ", "\u0a9f\u0acd\u0ab0\u0abe\u0aab\u0abf\u0a95 \u0ab8\u0abf\u0a97\u0acd\u0aa8\u0ab2 \u0ab2\u0abe\u0a88\u0a9f \u0aaa\u0abe\u0ab8\u0ac7..");
            Task_LanguageSelectActivity.this.handler.addQuestion(183, " \u0a95\u0abe\u0ab0 \u0aa8\u0abe \u0aa1\u0ac7\u0ab6 \u0aac\u0acb\u0ab0\u0acd\u0aa1 \u0a89\u0aaa\u0ab0 \u0ab2\u0a97\u0abe\u0ab5\u0ac7\u0ab2 \u0a9f\u0ac7\u0aae\u0acd\u0aaa\u0ab0\u0ac7\u0a9a\u0ab0 \u0aae\u0ac0\u0a9f\u0ab0 \u0ab6\u0ac7\u0aa8\u0ac1\u0a82 \u0aa4\u0abe\u0aaa\u0aae\u0abe\u0aa8 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a8f\u0aa8\u0acd\u0a9c\u0ac0\u0aa8 \u0aa8\u0ac1\u0a82 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(184, "\u0aab\u0ac2\u0a9f\u0aaa\u0abe\u0aa5 \u0ab5\u0a97\u0ab0 \u0aa8\u0abe \u0ab0\u0acb\u0aa1 \u0a89\u0aaa\u0ab0 \u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0 \u0a8f \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab5\u0ac1\u0a82?", "\u0ab0\u0acb\u0aa1 \u0aa8\u0ac0 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0a8f \u0a9a\u0abe\u0ab2\u0ab5\u0ac1\u0a82 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(185, "\u0aac\u0acd\u0ab0\u0ac7\u0a95 \u0ab2\u0abe\u0a88\u0a9f \u0ab5\u0a97\u0ab0 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0ac1\u0a82 \u0a8f ", "\u0a8f \u0a97\u0ac1\u0aa8\u0acd\u0ab9\u0acb \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(186, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0abe \u0ab5\u0abe\u0ab9\u0aa8\u0acb \u0aa8\u0ac7 \u0a9c\u0ab5\u0abe\u0aa8\u0ac0 \u0a85\u0a97\u0acd\u0ab0\u0aa4\u0abe \u0a86\u0aaa\u0ab5\u0ac0 \u0a9c\u0acb\u0a88\u0a8f.. ", "\u0a8f\u0aae\u0acd\u0aac\u0acd\u0aaf\u0ac1\u0ab2\u0aa8\u0acd\u0ab8 \u0a85\u0aa8\u0ac7 \u0aab\u0abe\u0aaf\u0ab0 \u0aab\u0abe\u0a88\u0a9f\u0ab0 \u0ab5\u0abe\u0ab9\u0aa8\u0acb ");
            Task_LanguageSelectActivity.this.handler.addQuestion(187, "\u0a95\u0abe\u0a9a\u0abe \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa8\u0ac0 \u0aae\u0ac1\u0aa6\u0aa4 \u0ab6\u0ac1\u0a82 \u0a9b\u0ac7? ", "\u0aec \u0aae\u0ab9\u0abf\u0aa8\u0abe ");
            Task_LanguageSelectActivity.this.handler.addQuestion(188, "\u0aa4\u0aae\u0ac7 \u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac7 \u0a95\u0a88 \u0aac\u0abe\u0a9c\u0ac1 \u0aa5\u0ac0 \u0a93\u0ab5\u0ab0\u0a9f\u0ac7\u0a95 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acb \u0a9b\u0acb? ", "\u0a86\u0a97\u0ab3 \u0aa8\u0abe \u0ab5\u0abe\u0ab9\u0aa8 \u0aa8\u0ac0 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0aa5\u0ac0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(189, "\u0aaa\u0acd\u0ab0\u0abe\u0aa5\u0aae\u0abf\u0a95 \u0ab8\u0abe\u0ab0\u0ab5\u0abe\u0ab0 \u0aae\u0abe\u0a82 \u0a8f\u0ab8.\u0aac\u0ac0.\u0ab8\u0ac0. \u0aa8\u0acb \u0a85\u0ab0\u0acd\u0aa5 \u0ab6\u0ac1\u0a82 \u0aa5\u0abe\u0aaf? ", "\u0a8f\u0ab0 \u0ab5\u0ac7, \u0aac\u0acd\u0ab0\u0ac0\u0aa7\u0ac0\u0a82\u0a97, \u0ab8\u0ab0\u0acd\u0a95\u0acd\u0aaf\u0ac1\u0ab2\u0ac7\u0ab6\u0aa8");
            Task_LanguageSelectActivity.this.handler.addQuestion(190, " \u0a9c\u0ac7 \u0ab0\u0acb\u0aa1 \u0ab5\u0aa8-\u0ab5\u0ac7 \u0aa4\u0ab0\u0ac0\u0a95\u0ac7 \u0a9c\u0abe\u0ab9\u0ac7\u0ab0 \u0aa5\u0aaf\u0ac7\u0ab2 \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0a82 ", "\u0ab0\u0ac0\u0ab5\u0ab0\u0acd\u0ab8 \u0a97\u0ac0\u0aaf\u0ab0 \u0aae\u0abe\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0ab5\u0ac1\u0a82 \u0aa8\u0ab9\u0abf.");
            Task_LanguageSelectActivity.this.handler.addQuestion(191, " \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0abe \u0ab8\u0a82\u0a9c\u0acb\u0a97\u0acb\u0aae\u0abe\u0a82 \u0aae\u0abe\u0aa8\u0ab5 \u0a9c\u0ac0\u0ab5\u0aa8\u0aa8\u0ac7 \u0aac\u0a9a\u0abe\u0ab5\u0ab5\u0abe \u0a95\u0aaf\u0abe \u0aaa\u0acd\u0ab0\u0a95\u0abe\u0ab0\u0aa8\u0ac1\u0a82 \u0a9c\u0acd\u0a9e\u0abe\u0aa8 \u0a86\u0aaa\u0aa8\u0ac7 \u0aae\u0aa6\u0aa6\u0ab0\u0ac2\u0aaa \u0aa5\u0a87 \u0ab6\u0a95\u0ac7 \u0a9b\u0ac7? ", "\u0aaa\u0acd\u0ab0\u0abe\u0aa5\u0aae\u0abf\u0a95 \u0ab8\u0abe\u0ab0\u0ab5\u0abe\u0ab0 ");
            Task_LanguageSelectActivity.this.handler.addQuestion(192, " \u0a85\u0aaf\u0acb\u0a97\u0acd\u0aaf \u0ab0\u0ac0\u0aa4\u0ac7 \u0a97\u0ac0\u0aaf\u0ab0 \u0aac\u0aa6\u0ab2\u0ab5\u0abe\u0aa5\u0ac0 ", "\u0aac\u0a82\u0aa8\u0ac7 \u0aa5\u0a87 \u0ab6\u0a95\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(193, "\u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0ab2\u0ac7\u0a88\u0aa8 \u0aac\u0aa6\u0ab2\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7..", "\u0a88\u0aa8\u0acd\u0aa1\u0ac0\u0a95\u0ac7\u0a9f\u0ab0 \u0aac\u0aa4\u0abe\u0aa1\u0acb \u0a85\u0aa8\u0ac7 \u0ab2\u0ac7\u0a88\u0aa8 \u0aac\u0aa6\u0ab2\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(194, " \u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aad\u0ac1\u0a82 \u0ab0\u0abe\u0a96\u0ab5\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aa1\u0abe\u0aac\u0ac0 \u0ab2\u0abe\u0a88\u0aa8\u0aae\u0abe\u0a82 \u0a9c\u0ab5\u0abe \u0aa4\u0aae\u0ac7.. ", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0aa8\u0ac0 \u0a88\u0aa8\u0acd\u0aa1\u0ac0\u0a95\u0ac7\u0a9f\u0ab0 \u0ab2\u0abe\u0a88\u0a9f \u0a9a\u0abe\u0ab2\u0ac1 \u0a95\u0ab0\u0ab6\u0acb. ");
            Task_LanguageSelectActivity.this.handler.addQuestion(195, " \u0ab5\u0abe\u0ab9\u0aa8 \u0aae\u0abe\u0a82 \u0a9f\u0abe\u0aaf\u0ab0\u0acb\u0aa8\u0ac0 \u0a86\u0a97\u0ab3 \u0aaa\u0abe\u0a9b\u0ab3 \u0aab\u0ac7\u0ab0 \u0aac\u0aa6\u0ab2\u0ac0 \u0a95\u0ab0\u0ab5\u0ac0 \u0a95\u0ac7\u0aae \u0ab8\u0ab2\u0abe\u0ab9 \u0aad\u0ab0\u0ac7\u0ab2 \u0a9b\u0ac7? ", "\u0a9f\u0abe\u0aaf\u0ab0\u0acb\u0aa8\u0ac7 \u0a85\u0ab8\u0abe\u0aae\u0abe\u0aa8\u0acd\u0aaf \u0a98\u0ab8\u0abe\u0ab0\u0acb \u0a85\u0a9f\u0a95\u0ac7 \u0a9b\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(196, "\u0ab8\u0a97\u0ac0\u0ab0 \u0aac\u0abe\u0ab3\u0a95 \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0abe \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0a95\u0ab0\u0ac7 \u0aa4\u0ac7.. ", "\u0a95\u0abe\u0aaf\u0aa6\u0ac7\u0ab8\u0ab0 \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0aab\u0ab0\u0abf\u0aaf\u0abe\u0aa6 \u0aa8\u0acb\u0a82\u0aa7\u0abe\u0ab5\u0ab5\u0ac0 \u0a85\u0aa8\u0ac7 \u0aa4\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa6\u0a82\u0aa1 \u0aa5\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(197, "\u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0abe \u0ab8\u0a82\u0a9c\u0acb\u0a97\u0acb \u0aae\u0abe\u0a82 \u0a95\u0acb\u0a88 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac7 \u0aaa\u0ac0\u0aa0/\u0a95\u0ab0\u0acb\u0aa1\u0ab0\u0a9c\u0acd\u0a9c\u0ac1\u0aae\u0abe\u0a82 \u0a88\u0a9c\u0abe \u0aa5\u0a87 \u0a9b\u0ac7 \u0aa4\u0acb \u0a86\u0aaa... ", "\u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac7 \u0a96\u0ab8\u0ac7\u0aa1\u0ab6\u0acb \u0aa8\u0ab9\u0abf \u0a85\u0aa8\u0ac7 \u0a85\u0aa8\u0acd\u0aaf \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95\u0acb\u0aa8\u0ac7 \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0a85\u0a82\u0a97\u0ac7 \u0a9a\u0ac7\u0aa4\u0ab5\u0aa3\u0ac0 \u0a86\u0aaa\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(198, "\u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4\u0aa8\u0abe \u0ab8\u0a82\u0a9c\u0acb\u0a97\u0acb\u0aae\u0abe\u0a82 \u0a95\u0acb\u0a88 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac0 \u0a9a\u0abe\u0aae\u0aa1\u0ac0 \u0aac\u0ab3\u0ac0 \u0a97\u0a88 \u0ab9\u0acb\u0aaf \u0aa4\u0acb \u0a86\u0aaa \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0aac\u0ab3\u0ac7\u0ab2\u0abe \u0aad\u0abe\u0a97\u0aa8\u0ac7 \u0aa0\u0a82\u0aa1\u0abe \u0aaa\u0abe\u0aa3\u0ac0\u0aa5\u0ac0 \u0aa7\u0acb\u0a88\u0aa8\u0ac7 \u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac7 \u0a9b\u0abe\u0aaf\u0aa1\u0abe\u0aae\u0abe\u0a82 \u0ab2\u0a87 \u0a9c\u0ab6\u0acb \u0a85\u0aa8\u0ac7 \u0a8f\u0aae\u0acd\u0aac\u0acd\u0aaf\u0ac1\u0ab2\u0aa8\u0acd\u0ab8 \u0aac\u0acb\u0ab2\u0abe\u0ab5\u0ab6\u0acb.");
            Task_LanguageSelectActivity.this.handler.addQuestion(201, " \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0ac7 \u0ab2\u0ac0\u0aa7\u0ac7 \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0aa4\u0acd\u0ab0\u0ac0\u0a9c\u0ac0 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac0 \u0ab8\u0a82\u0aaa\u0aa4\u0abf\u0aa8\u0ac7 \u0aa8\u0ac1\u0a95\u0ab6\u0abe\u0aa8 \u0aa5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95 \u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0ae8\u0aea \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(202, "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0aae\u0acb\u0a9f\u0ab0 \u0ab5\u0abe\u0ab9\u0aa8 \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aae\u0abe\u0a82 \u0ab8\u0a82\u0aa1\u0acb\u0ab5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0a86 \u0ab5\u0abe\u0ab9\u0aa8 \u0ab9\u0abe\u0a82\u0a95\u0aa8\u0abe\u0ab0.. ", "\u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0ae8\u0aea \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.");
            Task_LanguageSelectActivity.this.handler.addQuestion(203, "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0aab\u0abe\u0a9f\u0a95 \u0ab5\u0a97\u0ab0\u0aa8\u0abe \u0ab0\u0ac7\u0ab2\u0acd\u0ab5\u0ac7 \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 \u0aaa\u0abe\u0ab8\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0ab9\u0acb\u0a9a\u0ac7 \u0a9b\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0aab\u0abe\u0a9f\u0a95 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0aa4\u0abe \u0aaa\u0ab9\u0ac7\u0ab2\u0abe \u0a9a\u0abe\u0ab2\u0a95 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0ac7? ", "\u0ab0\u0ab8\u0acd\u0aa4\u0abe\u0aa8\u0ac0 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aad\u0ac1\u0a82 \u0ab0\u0abe\u0a96\u0ac0 \u0aa8\u0ac0\u0a9a\u0ac7 \u0a89\u0aa4\u0ab0\u0ac0\u0aa8\u0ac7 \u0a9a\u0abe\u0ab2\u0a95 \u0ab0\u0ac7\u0ab2\u0acd\u0ab5\u0ac7 \u0ab2\u0abe\u0a88\u0aa8 \u0a89\u0aaa\u0ab0 \u0a9c\u0a88\u0aa8\u0ac7 \u0a96\u0abe\u0aa4\u0ab0\u0ac0 \u0a95\u0ab0\u0ab6\u0ac7");
            Task_QueConstructor m_rtoTaskQueConstructor = new Task_QueConstructor(1, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0ab0\u0abe\u0a96\u0acb.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab9\u0abe\u0a82\u0a95\u0acb.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0aa8\u0aa5\u0ac0.", "\u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0ab0\u0abe\u0a96\u0acb.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor2 = new Task_QueConstructor(2, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa5\u0acb\u0aad\u0acb.", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa5\u0acb\u0aad\u0acb.", "\u0aa8\u0acb \u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97. ", "\u0a86\u0a97\u0ab3 \u0ab9\u0acb\u0ab8\u0acd\u0aaa\u0abf\u0a9f\u0ab2 \u0a9b\u0ac7.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor3 = new Task_QueConstructor(3, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0aa8\u0abe\u0ab8\u0acd\u0aa4\u0abe \u0aaa\u0abe\u0aa3\u0ac0 \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0acb \u0ab8\u0acd\u0a9f\u0acb\u0ab2 \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0aaa\u0ac1\u0ab2 \u0a9b\u0ac7.", "\u0aa8\u0abe\u0ab8\u0acd\u0aa4\u0abe \u0aaa\u0abe\u0aa3\u0ac0 \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0acb \u0ab8\u0acd\u0a9f\u0acb\u0ab2 \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0ab9\u0acb\u0aa1\u0ac0 \u0ab8\u0ac7\u0ab5\u0abe \u0a9b\u0ac7.", "photo");
            new Task_QueConstructor(4, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a9b\u0ac1\u0a9f\u0abe \u0aaa\u0aa5\u0acd\u0aa5\u0ab0 \u0ab5\u0abe\u0ab3\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb.", "\u0a9b\u0ac1\u0a9f\u0abe \u0aaa\u0aa5\u0acd\u0aa5\u0ab0 \u0ab5\u0abe\u0ab3\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb.", "\u0ab2\u0aaa\u0ab8\u0ac0 \u0a9c\u0ab5\u0abe\u0aaf \u0a8f\u0ab5\u0acb \u0a9a\u0ac0\u0a95\u0aa3\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb.", "\u0aae\u0acb\u0a9f\u0ab0 \u0a95\u0abe\u0ab0 \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aae\u0aa8\u0abe\u0a88.", "photo");
            new Task_QueConstructor(5, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0ac1\u0a82 \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97. ", "\u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aae\u0abe\u0a9f\u0ac7 \u0aa8\u0ac1\u0a82 \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97. ", "\u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aac\u0a82\u0aa7.", "photo");
            new Task_QueConstructor(6, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab5\u0abe\u0aaf \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0ab3\u0acb.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0ab3\u0acb.", "\u0ab5\u0abe\u0aaf \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "photo");
            new Task_QueConstructor(7, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0aaf \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0aaf \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0aaf \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab8\u0abe\u0a88\u0aa1 \u0ab0\u0acb\u0aa1 \u0a9b\u0ac7.", "photo");
            new Task_QueConstructor(8, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a86\u0a97\u0ab3 \u0ab8\u0abe\u0a82\u0a95\u0aa1\u0acb \u0aac\u0acd\u0ab0\u0ac0\u0a9c \u0a9b\u0ac7.", "\u0ab8\u0abe\u0aae\u0ac7 \u0aac\u0a82\u0aa8\u0ac7 \u0aa4\u0ab0\u0aab \u0ab0\u0acb\u0aa1 \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0ab8\u0abe\u0a82\u0a95\u0aa1\u0acb \u0aac\u0acd\u0ab0\u0ac0\u0a9c \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0ab8\u0abe\u0a82\u0a95\u0aa1\u0acb \u0ab0\u0acb\u0aa1 \u0a9b\u0ac7.", "photo");
            new Task_QueConstructor(9, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0aad\u0aaf\u0a9c\u0aa8\u0a95 \u0ab8\u0ac1\u0aaa\u0aa1\u0ac0 \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0ab8\u0abe\u0a82\u0a95\u0aa1\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9b\u0ac7.", "\u0aad\u0aaf\u0a9c\u0aa8\u0a95 \u0ab8\u0ac1\u0aaa\u0aa1\u0ac0 \u0a9b\u0ac7.", "\u0ab9\u0acb\u0aa1\u0ac0 \u0ab8\u0ac7\u0ab5\u0abe \u0a9b\u0ac7.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor4 = new Task_QueConstructor(10, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a86\u0a97\u0ab3 \u0ab8\u0abe\u0a82\u0a95\u0aa1\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0ab8\u0abe\u0a82\u0a95\u0aa1\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0ab8\u0abe\u0a82\u0a95\u0aa1\u0ac1\u0a82 \u0aa8\u0abe\u0ab3\u0ac1\u0a82 \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0aac\u0a82\u0aa8\u0ac7 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a9b\u0ac7.", "photo");
            new Task_QueConstructor(11, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a97\u0aa4\u0abf \u0aae\u0ab0\u0acd\u0aaf\u0abe\u0aa6\u0abe \u0aa8\u0acb \u0a85\u0a82\u0aa4.", "\u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0aac\u0a82\u0aa7 \u0a9b\u0ac7.", "\u0aaa\u0abe\u0ab0\u0acd\u0a95\u0abf\u0a82\u0a97 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0a97\u0aa4\u0abf \u0aae\u0ab0\u0acd\u0aaf\u0abe\u0aa6\u0abe \u0aa8\u0acb \u0a85\u0a82\u0aa4.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor5 = new Task_QueConstructor(12, " \u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0aab\u0abe\u0a9f\u0a95 \u0ab5\u0abe\u0ab3\u0ac1\u0a82 \u0ab0\u0ac7\u0ab2\u0acd\u0ab5\u0ac7 \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 \u0a9b\u0ac7.", "\u0aa8\u0a9c\u0ac0\u0a95 \u0aae\u0abe\u0a82 \u0ab0\u0ac7\u0ab2\u0acd\u0ab5\u0ac7 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0a9b\u0ac7.", "\u0aab\u0abe\u0a9f\u0a95 \u0ab5\u0a97\u0ab0\u0aa8\u0ac1\u0a82 \u0ab0\u0ac7\u0ab2\u0acd\u0ab5\u0ac7 \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 .", "\u0aab\u0abe\u0a9f\u0a95 \u0ab5\u0abe\u0ab3\u0ac1\u0a82 \u0ab0\u0ac7\u0ab2\u0acd\u0ab5\u0ac7 \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 \u0a9b\u0ac7.", "photo");
            new Task_QueConstructor(13, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a86\u0a97\u0ab3 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9b\u0ac7.", "\u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7. ", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor6 = new Task_QueConstructor(14, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a86\u0a97\u0ab3 \u0aae\u0ac1\u0a96\u0acd\u0aaf \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0a9a\u0abe\u0ab0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a9b\u0ac7.", "\u0a86\u0a97\u0ab3 \u0aae\u0ac1\u0a96\u0acd\u0aaf \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9b\u0ac7.", "\u0aab\u0ab8\u0acd\u0a9f \u0a8f\u0a87\u0aa1 ", "photo");
            new Task_QueConstructor(15, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab5\u0abe\u0a82\u0a95\u0acb \u0a9a\u0ac2\u0a95\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0ab5\u0abe\u0a82\u0a95\u0acb \u0a9a\u0ac2\u0a95\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0ab5\u0abe\u0a82\u0a95\u0acb \u0a9a\u0ac2\u0a95\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0abe\u0a82\u0a95 \u0ab2\u0a88\u0aa8\u0ac7 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0acb.", "photo");
            new Task_QueConstructor(16, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0ab5\u0abe\u0a82\u0a95\u0acb \u0a9a\u0ac2\u0a95\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0ab5\u0abe\u0a82\u0a95\u0acb \u0a9a\u0ac2\u0a95\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0ab5\u0abe\u0a82\u0a95\u0acb \u0a9a\u0ac2\u0a95\u0acb \u0ab0\u0ab8\u0acd\u0aa4\u0acb \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0abe\u0a82\u0a95 \u0ab2\u0a88\u0aa8\u0ac7 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0acb.", "photo");
            new Task_QueConstructor(17, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0a9a\u0ac0\u0aaa\u0abf\u0aaf\u0abe \u0a9c\u0ac7\u0ab5\u0acb \u0ab5\u0ab3\u0abe\u0a82\u0a95.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0aa2\u0abe\u0ab3.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0a9a\u0ac0\u0aaa\u0abf\u0aaf\u0abe \u0a9c\u0ac7\u0ab5\u0acb \u0ab5\u0ab3\u0abe\u0a82\u0a95.", "\u0ab5\u0abe\u0ab9\u0aa8 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0aa8\u0ac0 \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab0\u0abe\u0a96\u0acb.", "photo");
            new Task_QueConstructor(18, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0a9a\u0ac0\u0aaa\u0abf\u0aaf\u0abe \u0a9c\u0ac7\u0ab5\u0acb \u0ab5\u0ab3\u0abe\u0a82\u0a95.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0a9a\u0ac0\u0aaa\u0abf\u0aaf\u0abe \u0a9c\u0ac7\u0ab5\u0acb \u0ab5\u0ab3\u0abe\u0a82\u0a95.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0a9a\u0aa2\u0abe\u0aa3 \u0a85\u0aa8\u0ac7 \u0aa2\u0abe\u0ab3.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0aa2\u0abe\u0ab3.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor7 = new Task_QueConstructor(19, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "U-Turn \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1\u0aa5\u0ac0 \u0a93\u0ab5\u0ac7\u0ab0 \u0a9f\u0ac7\u0a95\u0abf\u0a82\u0a97 \u0aae\u0aa8\u0abe\u0a88.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor8 = new Task_QueConstructor(20, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "U-Turn \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "U-Turn \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0a9c\u0aae\u0aa3\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0ab3\u0ab5\u0abe\u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1\u0aa5\u0ac0 \u0a93\u0ab5\u0ac7\u0ab0 \u0a9f\u0ac7\u0a95\u0abf\u0a82\u0a97 \u0aae\u0aa8\u0abe\u0a88.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor9 = new Task_QueConstructor(21, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0aac\u0ab3\u0aa6\u0a97\u0abe\u0aa1\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0aac\u0ab3\u0aa6\u0a97\u0abe\u0aa1\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0aac\u0aa7\u0abe \u0a9c \u0ab5\u0abe\u0ab9\u0aa8\u0acb \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor10 = new Task_QueConstructor(22, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0a9f\u0acd\u0ab0\u0a95 \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0a9f\u0acd\u0ab0\u0a95 \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0aac\u0ab8 \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "\u0ab9\u0ac7\u0ab5\u0ac0 \u0ab5\u0abe\u0ab9\u0aa8\u0acb \u0aae\u0abe\u0a9f\u0ac7 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6 \u0aa8\u0ac0 \u0aae\u0aa8\u0abe\u0a88 \u0a9b\u0ac7.", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor11 = new Task_QueConstructor(23, "\u0aa8\u0ac0\u0a9a\u0ac7 \u0aae\u0ac1\u0a9c\u0aac \u0aa8\u0ac0 \u0aa8\u0abf\u0ab6\u0abe\u0aa8\u0ac0 \u0ab6\u0ac1\u0a82 \u0aac\u0aa4\u0abe\u0ab5\u0ac7 \u0a9b\u0ac7? ", "\u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0acb \u0a85\u0aa5\u0ab5\u0abe \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0ab9\u0aa8 \u0ab5\u0abe\u0ab3\u0ac0 \u0ab6\u0a95\u0abe\u0aaf.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0ab3\u0ac0 \u0ab6\u0a95\u0abe\u0aaf.", "\u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0acb \u0a85\u0aa5\u0ab5\u0abe \u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab5\u0abe\u0ab9\u0aa8 \u0ab5\u0abe\u0ab3\u0ac0 \u0ab6\u0a95\u0abe\u0aaf.", "\u0aa1\u0abe\u0aac\u0ac0 \u0aac\u0abe\u0a9c\u0ac1 \u0ab8\u0abe\u0a88\u0aa1 \u0ab0\u0acb\u0aa1 \u0a9b\u0ac7.", "photo");
