            Task_QueConstructor m_rtoTaskQueConstructor114 = new Task_QueConstructor(126, "\u0ab8\u0aab\u0ac7\u0aa6 \u0ab0\u0a82\u0a97\u0aa5\u0ac0 \u0ab0\u0ab8\u0acd\u0aa4\u0abe \u0a89\u0aaa\u0ab0 \u0aa4\u0ac2\u0a9f\u0a95-\u0aa4\u0ac2\u0a9f\u0a95 \u0ab2\u0abe\u0a88\u0aa8 \u0a9a\u0ac0\u0aa4\u0ab0\u0ac7\u0ab2\u0ac0 \u0ab9\u0acb\u0aaf \u0aa4\u0acb \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0a9c\u0ab0\u0ac2\u0ab0 \u0aaa\u0aa1\u0ac7 \u0aa4\u0acb track \u0aac\u0aa6\u0ab2\u0ab6\u0acb.", "\u0aa4\u0aae\u0ac7 track \u0aac\u0aa6\u0ab2\u0ab6\u0acb \u0aa8\u0ab9\u0abf.", "\u0a9c\u0ab0\u0ac2\u0ab0 \u0aaa\u0aa1\u0ac7 \u0aa4\u0acb track \u0aac\u0aa6\u0ab2\u0ab6\u0acb.", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa5\u0acb\u0aad\u0abe\u0ab5\u0ac0 \u0aa6\u0ac7\u0ab6\u0acb.", "nophoto");
