            Task_QueConstructor m_rtoTaskQueConstructor116 = new Task_QueConstructor(128, "\u0ab5\u0ab0\u0ab8\u0abe\u0aa6 \u0aae\u0abe\u0a82 \u0aac\u0acd\u0ab0\u0ac7\u0a95 \u0ab2\u0a97\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0ab8\u0acd\u0a9f\u0acb\u0aaa\u0ac0\u0a82\u0a97 \u0aa1\u0abf\u0ab8\u0acd\u0a9f\u0aa8\u0acd\u0ab8 \u0a89\u0aaa\u0ab0 \u0ab6\u0ac1\u0a82 \u0a85\u0ab8\u0ab0 \u0aaa\u0aa1\u0ac7 \u0a9b\u0ac7? ", "\u0ab8\u0acd\u0a9f\u0acb\u0aaa\u0ac0\u0a82\u0a97 \u0aa1\u0abf\u0ab8\u0acd\u0a9f\u0aa8\u0acd\u0ab8 \u0ab5\u0aa7\u0ac7 \u0a9b\u0ac7.", "\u0ab8\u0acd\u0a9f\u0acb\u0aaa\u0ac0\u0a82\u0a97 \u0aa1\u0abf\u0ab8\u0acd\u0a9f\u0aa8\u0acd\u0ab8 \u0ab5\u0aa7\u0ac7 \u0a9b\u0ac7.", "\u0ab8\u0acd\u0a9f\u0acb\u0aaa\u0ac0\u0a82\u0a97 \u0aa1\u0abf\u0ab8\u0acd\u0a9f\u0aa8\u0acd\u0ab8 \u0a93\u0a9b\u0ac1 \u0aa5\u0abe\u0aaf \u0a9b\u0ac7.", "\u0a95\u0acb\u0a88 \u0a85\u0ab8\u0ab0 \u0aa5\u0aa4\u0ac0 \u0aa8\u0aa5\u0ac0", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor117 = new Task_QueConstructor(129, " \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0ab2\u0abe\u0ab5\u0aa4\u0ac0 \u0ab5\u0a96\u0aa4\u0ac7 \u0a9a\u0abe\u0ab2\u0a95\u0ac7 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0a95\u0aaf\u0abe \u0ab8\u0acd\u0ab5\u0ab0\u0ac2\u0aaa\u0ac7 \u0ab8\u0abe\u0aa5\u0ac7 \u0ab0\u0abe\u0a96\u0ab5\u0ac1\u0a82 \u0aab\u0ab0\u0a9c\u0ac0\u0aaf\u0abe\u0aa4 \u0a9b\u0ac7? ", "\u0a85\u0ab8\u0ab2 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8", "\u0a85\u0ab8\u0ab2 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8", "\u0ab0\u0a82\u0a97\u0ac0\u0aa8 \u0a9d\u0ac7\u0ab0\u0acb\u0a95\u0acd\u0ab7 ", "\u0aaa\u0acd\u0ab0\u0aae\u0abe\u0aa3\u0abf\u0aa4 \u0aa8\u0a95\u0ab2", "nophoto");
