            Task_QueConstructor m_rtoTaskQueConstructor121 = new Task_QueConstructor(133, "\u0aa4\u0aae\u0ac7 \u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aa8\u0ac1\u0a82 \u0ab2\u0aa8\u0ab0\u0acd\u0ab8 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa7\u0ab0\u0abe\u0ab5\u0aa4\u0abe \u0ab9\u0acb\u0aaf \u0aa4\u0acb.. ", "\u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aa8\u0ac1\u0a82 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa7\u0ab0\u0abe\u0ab5\u0aa8\u0abe\u0ab0 \u0a87\u0aa8\u0ab8\u0acd\u0a9f\u0acd\u0ab0\u0a95\u0a9f\u0ab0 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0ab8\u0abe\u0aa5\u0ac7 \u0ab9\u0ab6\u0ac7 \u0aa4\u0acb \u0a9c \u0aa4\u0aae\u0ac7 \u0ab9\u0abe\u0a95\u0ab6\u0acb.", "\u0aa4\u0aae\u0ac7 \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0a9f\u0acd\u0ab0\u0abe\u0aab\u0abf\u0a95 \u0a93\u0a9b\u0acb \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0ab9\u0abe\u0a95\u0ab6\u0acb.", "\u0aae\u0acb\u0a9f\u0ab0 \u0ab8\u0abe\u0a87\u0a95\u0ab2 \u0aa8\u0ac1\u0a82 \u0ab2\u0abe\u0a87\u0ab8\u0aa8\u0acd\u0ab8 \u0aa7\u0ab0\u0abe\u0ab5\u0aa8\u0abe\u0ab0 \u0a87\u0aa8\u0ab8\u0acd\u0a9f\u0acd\u0ab0\u0a95\u0a9f\u0ab0 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0ab8\u0abe\u0aa5\u0ac7 \u0ab9\u0ab6\u0ac7 \u0aa4\u0acb \u0a9c \u0aa4\u0aae\u0ac7 \u0ab9\u0abe\u0a95\u0ab6\u0acb.", "\u0aa4\u0aae\u0ac7 \u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aaa\u0ab0 \u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac7 \u0aaa\u0abe\u0a9b\u0ab3 \u0aac\u0ac7\u0ab8\u0abe\u0aa1\u0ab6\u0acb", "nophoto");
