            Task_QueConstructor m_rtoTaskQueConstructor127 = new Task_QueConstructor(139, "\u0aa4\u0aae\u0ac7 \u0ab8\u0abe\u0a82\u0a95\u0ab3\u0abe \u0aa8\u0abe\u0ab3\u0abe \u0aaa\u0abe\u0ab8\u0ac7 \u0aaa\u0ab9\u0acb\u0a9a\u0acb \u0a9b\u0acb, \u0ab8\u0abe\u0aae\u0ac7\u0aa5\u0ac0 \u0aa8\u0abe\u0ab3\u0abe \u0aae\u0abe\u0a82 \u0aac\u0ac0\u0a9c\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0acd\u0ab0\u0ab5\u0ac7\u0ab6\u0ac7 \u0a9b\u0ac7, \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb?", "\u0ab8\u0abe\u0aae\u0ac7\u0aa8\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0ab8\u0abe\u0ab0 \u0aa5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0a82 \u0ab8\u0ac1\u0aa7\u0ac0 \u0aa5\u0acb\u0aad\u0ac0 \u0aa4\u0acd\u0aaf\u0abe\u0ab0 \u0aac\u0abe\u0aa6 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.", "\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0a9d\u0aa1\u0aaa \u0ab5\u0aa7\u0abe\u0ab0\u0ac0 \u0a9c\u0ac7\u0aae \u0aac\u0aa8\u0ac7 \u0aa4\u0ac7\u0aae \u0a9d\u0aa1\u0aaa \u0aa5\u0ac0 \u0aa8\u0abe\u0ab3\u0ac1\u0a82 \u0aaa\u0ab8\u0abe\u0ab0 \u0a95\u0ab0\u0ab6\u0acb.", "\u0ab9\u0ac7\u0aa1 \u0ab2\u0abe\u0a88\u0a9f \u0a9a\u0abe\u0ab2\u0ac1 \u0a95\u0ab0\u0ac0 \u0aa8\u0abe\u0ab3\u0ac1\u0a82 \u0aaa\u0ab8\u0abe\u0ab0 \u0a95\u0ab0\u0ab6\u0acb.", "\u0ab8\u0abe\u0aae\u0ac7\u0aa8\u0ac1\u0a82 \u0ab5\u0abe\u0ab9\u0aa8 \u0aaa\u0ab8\u0abe\u0ab0 \u0aa5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0a82 \u0ab8\u0ac1\u0aa7\u0ac0 \u0aa5\u0acb\u0aad\u0ac0 \u0aa4\u0acd\u0aaf\u0abe\u0ab0 \u0aac\u0abe\u0aa6 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor128 = new Task_QueConstructor(140, "\u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0\u0a93 \u0aae\u0abe\u0a9f\u0ac7\u0aa8\u0abe \u0a95\u0acd\u0ab0\u0acb\u0ab8\u0abf\u0a82\u0a97 \u0a89\u0aaa\u0ab0 \u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ab5\u0abe \u0a89\u0aad\u0abe \u0ab9\u0acb\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0aa4\u0aae\u0ac7 \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aad\u0ac1\u0a82 \u0ab0\u0abe\u0a96\u0ac0 \u0aa6\u0a88 \u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0\u0a93 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ac0 \u0ab2\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0a82 \u0ab8\u0ac1\u0aa7\u0ac0 \u0aa5\u0acb\u0aad\u0ac0 \u0aaa\u0a9b\u0ac0 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.", "\u0ab9\u0acb\u0ab0\u0acd\u0aa8 \u0ab5\u0a97\u0abe\u0aa1\u0ac0 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.", "\u0ab5\u0abe\u0ab9\u0aa8 \u0aa7\u0ac0\u0aae\u0ac1\u0a82 \u0aaa\u0abe\u0aa1\u0ac0\u0aa8\u0ac7 \u0ab9\u0acb\u0ab0\u0acd\u0aa8 \u0ab5\u0a97\u0abe\u0aa1\u0ac0 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a89\u0aad\u0ac1\u0a82 \u0ab0\u0abe\u0a96\u0ac0 \u0aa6\u0a88 \u0ab0\u0abe\u0ab9\u0aa6\u0abe\u0ab0\u0ac0\u0a93 \u0ab0\u0acb\u0aa1 \u0a95\u0acd\u0ab0\u0acb\u0ab8 \u0a95\u0ab0\u0ac0 \u0ab2\u0ac7 \u0aa4\u0acd\u0aaf\u0abe\u0a82 \u0ab8\u0ac1\u0aa7\u0ac0 \u0aa5\u0acb\u0aad\u0ac0 \u0aaa\u0a9b\u0ac0 \u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0ab6\u0acb.", "nophoto");
