            Task_QueConstructor m_rtoTaskQueConstructor184 = new Task_QueConstructor(196, "\u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0abe \u0ab8\u0a82\u0a9c\u0acb\u0a97\u0acb \u0aae\u0abe\u0a82 \u0a95\u0acb\u0a88 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac7 \u0aaa\u0ac0\u0aa0/\u0a95\u0ab0\u0acb\u0aa1\u0ab0\u0a9c\u0acd\u0a9c\u0ac1\u0aae\u0abe\u0a82 \u0a88\u0a9c\u0abe \u0aa5\u0a87 \u0a9b\u0ac7 \u0aa4\u0acb \u0a86\u0aaa... ", "\u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac7 \u0a96\u0ab8\u0ac7\u0aa1\u0ab6\u0acb \u0aa8\u0ab9\u0abf \u0a85\u0aa8\u0ac7 \u0a85\u0aa8\u0acd\u0aaf \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95\u0acb\u0aa8\u0ac7 \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0a85\u0a82\u0a97\u0ac7 \u0a9a\u0ac7\u0aa4\u0ab5\u0aa3\u0ac0 \u0a86\u0aaa\u0ab6\u0acb.", "\u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac7 \u0a8a\u0a82\u0a9a\u0a95\u0ac0\u0aa8\u0ac7 \u0ab8\u0ab2\u0abe\u0aae\u0aa4 \u0ab8\u0acd\u0aa5\u0ab3\u0ac7 \u0ab2\u0a87 \u0a9c\u0ab6\u0acb.", "\u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac7 \u0a96\u0ab8\u0ac7\u0aa1\u0ab6\u0acb \u0aa8\u0ab9\u0abf \u0a85\u0aa8\u0ac7 \u0a85\u0aa8\u0acd\u0aaf \u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95\u0acb\u0aa8\u0ac7 \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0a85\u0a82\u0a97\u0ac7 \u0a9a\u0ac7\u0aa4\u0ab5\u0aa3\u0ac0 \u0a86\u0aaa\u0ab6\u0acb.", "\u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0abe \u0aaa\u0a97 \u0a89\u0a9a\u0abe \u0a95\u0ab0\u0ac0\u0aa8\u0ac7 \u0a87\u0a9c\u0aa8\u0ac7 \u0aa4\u0aaa\u0abe\u0ab8\u0ab6\u0acb.", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor185 = new Task_QueConstructor(197, "\u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4\u0aa8\u0abe \u0ab8\u0a82\u0a9c\u0acb\u0a97\u0acb\u0aae\u0abe\u0a82 \u0a95\u0acb\u0a88 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf \u0aa8\u0ac0 \u0a9a\u0abe\u0aae\u0aa1\u0ac0 \u0aac\u0ab3\u0ac0 \u0a97\u0a88 \u0ab9\u0acb\u0aaf \u0aa4\u0acb \u0a86\u0aaa \u0ab6\u0ac1\u0a82 \u0a95\u0ab0\u0ab6\u0acb? ", "\u0aac\u0ab3\u0ac7\u0ab2\u0abe \u0aad\u0abe\u0a97\u0aa8\u0ac7 \u0aa0\u0a82\u0aa1\u0abe \u0aaa\u0abe\u0aa3\u0ac0\u0aa5\u0ac0 \u0aa7\u0acb\u0a88\u0aa8\u0ac7 \u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac7 \u0a9b\u0abe\u0aaf\u0aa1\u0abe\u0aae\u0abe\u0a82 \u0ab2\u0a87 \u0a9c\u0ab6\u0acb \u0a85\u0aa8\u0ac7 \u0a8f\u0aae\u0acd\u0aac\u0acd\u0aaf\u0ac1\u0ab2\u0aa8\u0acd\u0ab8 \u0aac\u0acb\u0ab2\u0abe\u0ab5\u0ab6\u0acb.", "\u0aac\u0ab3\u0ac7\u0ab2\u0abe \u0aad\u0abe\u0a97\u0aa8\u0ac7 \u0aa0\u0a82\u0aa1\u0abe \u0aaa\u0abe\u0aa3\u0ac0\u0aa5\u0ac0 \u0aa7\u0acb\u0a88\u0aa8\u0ac7 \u0a98\u0abe\u0aaf\u0ab2 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac7 \u0a9b\u0abe\u0aaf\u0aa1\u0abe\u0aae\u0abe\u0a82 \u0ab2\u0a87 \u0a9c\u0ab6\u0acb \u0a85\u0aa8\u0ac7 \u0a8f\u0aae\u0acd\u0aac\u0acd\u0aaf\u0ac1\u0ab2\u0aa8\u0acd\u0ab8 \u0aac\u0acb\u0ab2\u0abe\u0ab5\u0ab6\u0acb.", "\u0aab\u0acb\u0ab2\u0acd\u0ab2\u0abe \u0aaa\u0aa1\u0acd\u0aaf\u0abe \u0ab9\u0acb\u0aaf \u0aa4\u0acb \u0aa4\u0ac7 \u0aab\u0acb\u0aa1\u0ab6\u0acb.", "\u0a9a\u0abe\u0aae\u0aa1\u0ac0 \u0ab8\u0abe\u0aa5\u0ac7 \u0a9a\u0acb\u0a9f\u0ac7\u0ab2\u0abe \u0a95\u0aaa\u0aa1\u0abe \u0a89\u0a96\u0abe\u0aa1\u0ab6\u0acb.", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor186 = new Task_QueConstructor(198, " \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aa8\u0ac7 \u0ab2\u0ac0\u0aa7\u0ac7 \u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0aa4\u0acd\u0ab0\u0ac0\u0a9c\u0ac0 \u0ab5\u0acd\u0aaf\u0a95\u0acd\u0aa4\u0abf\u0aa8\u0ac0 \u0ab8\u0a82\u0aaa\u0aa4\u0abf\u0aa8\u0ac7 \u0aa8\u0ac1\u0a95\u0ab6\u0abe\u0aa8 \u0aa5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 ", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95 \u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0ae8\u0aea \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95 \u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0ae8\u0aea \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.", "\u0ab5\u0abe\u0ab9\u0aa8 \u0a9a\u0abe\u0ab2\u0a95 \u0aa8\u0a9c\u0ac0\u0a95\u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0aed \u0aa6\u0abf\u0ab5\u0ab8 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.", "\u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab5\u0abe\u0aa8\u0ac0 \u0a9c\u0ab0\u0ac2\u0ab0 \u0aa8\u0aa5\u0ac0.", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor187 = new Task_QueConstructor(199, "\u0a9c\u0aaf\u0abe\u0ab0\u0ac7 \u0aae\u0acb\u0a9f\u0ab0 \u0ab5\u0abe\u0ab9\u0aa8 \u0a85\u0a95\u0ab8\u0acd\u0aae\u0abe\u0aa4 \u0aae\u0abe\u0a82 \u0ab8\u0a82\u0aa1\u0acb\u0ab5\u0abe\u0aaf \u0aa4\u0acd\u0aaf\u0abe\u0ab0\u0ac7 \u0a86 \u0ab5\u0abe\u0ab9\u0aa8 \u0ab9\u0abe\u0a82\u0a95\u0aa8\u0abe\u0ab0.. ", "\u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0ae8\u0aea \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.", "\u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0ae8\u0aea \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.", "\u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0ae7\u0ae8 \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.", "\u0aa8\u0a9c\u0ac0\u0a95 \u0aa8\u0abe \u0aaa\u0acb\u0ab2\u0ac0\u0ab8 \u0ab8\u0acd\u0a9f\u0ac7\u0ab6\u0aa8 \u0aae\u0abe\u0a82 \u0aea\u0aee \u0a95\u0ab2\u0abe\u0a95 \u0aae\u0abe\u0a82 \u0a9c\u0abe\u0aa3 \u0a95\u0ab0\u0ab6\u0ac7.", "nophoto");
