            Task_QueConstructor m_rtoTaskQueConstructor6 = new Task_QueConstructor(12, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0915\u093e \u092e\u093e\u0930\u094d\u0917", "\u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0915\u093e \u092e\u093e\u0930\u094d\u0917", "\u092d\u093e\u0917\u094b \u092e\u0924", "\u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0915\u094b \u0928\u093f\u0937\u093f\u0926\u094d\u0927", "photo");
            new Task_QueConstructor(13, "\u0906\u092a \u090f\u0915 \u092a\u0930\u093f\u0935\u0939\u0928 \u0935\u093e\u0939\u0928 \u0915\u094b \u0915\u0948\u0938\u0947 \u092a\u0939\u091a\u093e\u0928 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "\u0935\u093e\u0939\u0928 \u0915\u0940 \u0928\u0902\u092c\u0930 \u092a\u094d\u0932\u0947\u091f \u0915\u094b \u0926\u0947\u0916\u0915\u0930", "\u091f\u093e\u092f\u0930 \u0906\u0915\u093e\u0930 \u0915\u094b \u0926\u0947\u0916\u0924\u0947 \u0939\u0941\u090f", "\u0935\u093e\u0939\u0928 \u0915\u0947 \u0930\u0902\u0917 \u0938\u0947", "\u0935\u093e\u0939\u0928 \u0915\u0940 \u0928\u0902\u092c\u0930 \u092a\u094d\u0932\u0947\u091f \u0915\u094b \u0926\u0947\u0916\u0915\u0930", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor7 = new Task_QueConstructor(14, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0926\u093e\u0908\u0902 \u0913\u0930 \u092a\u093e\u0930\u094d\u0915\u093f\u0902\u0917 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f", "\u0926\u093e\u0908\u0902 \u092a\u0915\u094d\u0937 \u0930\u0916\u0947\u0902", "\u0926\u093e\u0908\u0902 \u0913\u0930 \u092a\u093e\u0930\u094d\u0915\u093f\u0902\u0917 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f", "\u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f \u0913\u0930 \u0938\u0947 \u0938\u0939\u0940", "photo");
            new Task_QueConstructor(15, "\u0936\u093f\u0915\u094d\u0937\u093e\u0930\u094d\u0925\u0940 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0915\u0940 \u0935\u0948\u0927\u0924\u093e", "6 \u092e\u0939\u0940\u0928\u0947", "\u091c\u092c \u0924\u0915 \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948", "6 \u092e\u0939\u0940\u0928\u0947", "\u0924\u0940\u0938 \u0926\u093f\u0928", "nophoto");
            new Task_QueConstructor(16, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0926\u093e\u0908\u0902 \u0913\u0930 \u0928\u093f\u0937\u093f\u0926\u094d\u0927", "\u092f\u0942-\u091f\u0930\u094d\u0928 \u0928\u093f\u0937\u093f\u0926\u094d\u0927", "\u0926\u093e\u0908\u0902 \u0913\u0930 \u0928\u093f\u0937\u093f\u0926\u094d\u0927", "\u092c\u093e\u0908\u0902 \u0924\u0930\u092b \u0938\u0947 \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u0928\u0947 \u092a\u0930 \u0928\u093f\u0937\u093f\u0926\u094d\u0927", "photo");
            new Task_QueConstructor(17, "\u092c\u093f\u0928\u093e \u0915\u093f\u0938\u0940 \u092b\u0941\u091f\u092a\u093e\u0925 \u0915\u0947 \u0938\u0921\u093c\u0915 \u092a\u0930, \u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902\u0915\u094b", "\u0938\u0921\u093c\u0915 \u0915\u0947 \u0926\u093e\u0939\u093f\u0928\u0940 \u0913\u0930 \u091a\u0932\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0938\u0921\u093c\u0915 \u0915\u0947 \u092c\u093e\u0908\u0902 \u0913\u0930 \u091a\u0932\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0938\u0921\u093c\u0915 \u0915\u0947 \u0926\u093e\u0939\u093f\u0928\u0940 \u0913\u0930 \u091a\u0932\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0938\u0921\u093c\u0915 \u0915\u0947 \u0926\u094b\u0928\u094b\u0902 \u0913\u0930 \u091a\u0932\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "nophoto");
            new Task_QueConstructor(18, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0939\u0949\u0930\u094d\u0928 \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927\u093f\u0924", "\u0939\u0949\u0930\u094d\u0928 \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927\u093f\u0924", "\u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f \u0927\u094d\u0935\u0928\u093f \u0939\u0949\u0930\u094d\u0928", "\u0927\u094d\u0935\u0928\u093f \u0939\u0949\u0930\u094d\u0928", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor8 = new Task_QueConstructor(19, "\u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u092a\u094d\u0930\u0915\u093e\u0930 \u0915\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u094b \u0906\u091c\u093c\u093e\u0926 \u092e\u093e\u0930\u094d\u0917 \u0926\u093f\u092f\u093e \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u090f\u092e\u094d\u092c\u0941\u0932\u0947\u0902\u0938 \u0914\u0930 \u092b\u093e\u092f\u0930 \u0938\u0930\u094d\u0935\u093f\u0938 \u0935\u093e\u0939\u0928", "\u092a\u0941\u0932\u093f\u0938 \u0935\u093e\u0939\u0928", "\u090f\u092e\u094d\u092c\u0941\u0932\u0947\u0902\u0938 \u0914\u0930 \u092b\u093e\u092f\u0930 \u0938\u0930\u094d\u0935\u093f\u0938 \u0935\u093e\u0939\u0928", "\u090f\u0915\u094d\u0938\u092a\u094d\u0930\u0947\u0938 \u0914\u0930 \u0938\u0941\u092a\u0930 \u090f\u0915\u094d\u0938\u092a\u094d\u0930\u0947\u0938 \u092c\u0938\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor9 = new Task_QueConstructor(20, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0906\u0917\u0947 \u0938\u0902\u0915\u0940\u0930\u094d\u0923 \u092a\u0941\u0932", "\u0938\u093e\u092e\u0928\u0947 \u0926\u094b\u0928\u094b\u0902 \u0924\u0930\u092b \u0938\u0921\u093c\u0915\u0947\u0902", "\u0906\u0917\u0947 \u0938\u0902\u0915\u0940\u0930\u094d\u0923 \u092a\u0941\u0932", "\u0938\u0902\u0915\u0940\u0930\u094d\u0923 \u0938\u0921\u093c\u0915 \u0906\u0917\u0947", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor10 = new Task_QueConstructor(21, "\u0935\u093f\u092a\u0930\u0940\u0924 \u0926\u093f\u0936\u093e \u0938\u0947 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u094b \u0915\u093f\u0938 \u0924\u0930\u092b \u0938\u0947 \u092a\u093e\u0930\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0926\u0940 \u091c\u093e\u0928\u0940 \u091a\u093e\u0939\u093f\u090f?", "\u0906\u092a\u0915\u0940 \u0926\u093e\u0939\u093f\u0928\u0940 \u0913\u0930 \u0938\u0947", "\u0906\u092a\u0915\u0940 \u0926\u093e\u0939\u093f\u0928\u0940 \u0913\u0930 \u0938\u0947", "\u0906\u092a\u0915\u0940 \u092c\u093e\u0908\u0902 \u0913\u0930 \u0938\u0947", "\u0938\u0941\u0935\u093f\u0927\u093e\u091c\u0928\u0915 \u092a\u0915\u094d\u0937 \u0938\u0947", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor11 = new Task_QueConstructor(22, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0905\u0938\u094d\u092a\u0924\u093e\u0932", "\u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u093e \u092a\u0926", "\u0936\u093e\u0902\u0924 \u0938\u094d\u0925\u093e\u0928", "\u0905\u0938\u094d\u092a\u0924\u093e\u0932", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor12 = new Task_QueConstructor(23, "\u090f\u0915 \u0935\u093e\u0939\u0928 \u0915\u093e \u091a\u093e\u0932\u0915 \u0906\u0917\u0947 \u0928\u093f\u0915\u0932 \u0938\u0915\u0924\u093e \u0939\u0948,", "\u091c\u092c \u0938\u093e\u092e\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928 \u0915\u093e \u091a\u093e\u0932\u0915 \u0913\u0935\u0930\u091f\u0947\u0915 \u0915\u093e \u0938\u093f\u0917\u094d\u0928\u0932 \u0926\u093f\u0916\u093e\u0924\u093e \u0939\u0948", "\u092a\u0939\u093e\u0921\u093c \u0915\u0947 \u0928\u0940\u091a\u0947 \u091a\u0932\u093e\u0924\u0947 \u0938\u092e\u092f", "\u092f\u0926\u093f \u0938\u0921\u093c\u0915 \u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u091a\u094c\u0921\u093c\u0940 \u0939\u0948", "\u091c\u092c \u0938\u093e\u092e\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928 \u0915\u093e \u091a\u093e\u0932\u0915 \u0913\u0935\u0930\u091f\u0947\u0915 \u0915\u093e \u0938\u093f\u0917\u094d\u0928\u0932 \u0926\u093f\u0916\u093e\u0924\u093e \u0939\u0948", "nophoto");
