            Task_QueConstructor m_rtoTaskQueConstructor45 = new Task_QueConstructor(56, "\u092e\u094b\u092c\u093e\u0907\u0932 \u092b\u094b\u0928 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e", "\u090f\u0915 \u0935\u093e\u0939\u0928 \u091a\u0932\u093e\u0924\u0947 \u0938\u092e\u092f", "\u0938\u0930\u0915\u093e\u0930\u0940 \u0915\u093e\u0930\u094d\u092f\u093e\u0932\u092f\u094b\u0902 \u092e\u0947\u0902", "\u092a\u0941\u0932\u093f\u0938 \u0938\u094d\u091f\u0947\u0936\u0928\u094b\u0902 \u092e\u0947\u0902", "\u090f\u0915 \u0935\u093e\u0939\u0928 \u091a\u0932\u093e\u0924\u0947 \u0938\u092e\u092f", "nophoto");
