            Task_QueConstructor m_rtoTaskQueConstructor47 = new Task_QueConstructor(58, "\u0905\u0924\u093f\u0930\u0902\u091c\u0928\u093e \u0928\u093f\u0937\u093f\u0926\u094d\u0927 \u0939\u0948", "\u091c\u092c \u0938\u0921\u093c\u0915 \u0906\u0917\u0947 \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u0926\u093f\u0916\u093e\u0908 \u0928\u0939\u0940\u0902 \u0926\u0947 \u0930\u0939\u0940 \u0939\u0948", "\u091c\u092c \u0938\u0921\u093c\u0915 \u0906\u0917\u0947 \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u0926\u093f\u0916\u093e\u0908 \u0928\u0939\u0940\u0902 \u0926\u0947 \u0930\u0939\u0940 \u0939\u0948", "\u091c\u092c \u0938\u0921\u093c\u0915 \u0906\u0917\u0947 \u091a\u094c\u0921\u093c\u093e \u0939\u0948", "\u091c\u092c \u0938\u0921\u093c\u0915 \u0915\u093e \u0915\u0947\u0902\u0926\u094d\u0930 \u0938\u092b\u0947\u0926 \u091f\u0942\u091f\u0940 \u0939\u0941\u0908 \u0930\u0947\u0916\u093e\u0913\u0902 \u0938\u0947 \u091a\u093f\u0939\u094d\u0928\u093f\u0924 \u0939\u094b\u0924\u093e \u0939\u0948", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor48 = new Task_QueConstructor(59, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0935\u093e\u0939\u0928 \u0915\u094b 50 \u0915\u093f\u092e\u0940 / \u0918\u0902\u091f\u093e \u0938\u0947 \u0905\u0927\u093f\u0915 \u0928\u0939\u0940\u0902 \u091a\u0932\u093e\u0928\u093e", "\u0935\u093e\u0939\u0928 \u0915\u094b 50 \u0915\u093f\u092e\u0940 / \u0918\u0902\u091f\u093e \u0938\u0947 \u0905\u0927\u093f\u0915 \u0928\u0939\u0940\u0902 \u091a\u0932\u093e\u0928\u093e", "\u0935\u093e\u0939\u0928 \u0915\u094b 50 \u0915\u093f\u092e\u0940 / \u0918\u0902\u091f\u093e \u092a\u0930 \u0921\u094d\u0930\u093e\u0907\u0935 \u0915\u0930\u0947\u0902", "50 \u0915\u093f\u092e\u0940 / \u0918\u0902\u091f\u093e \u0938\u0947 \u0905\u0927\u093f\u0915 \u0935\u093e\u0939\u0928 \u091a\u0932\u093e\u090f\u0902", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor49 = new Task_QueConstructor(60, "\u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0915\u094b \u0924\u0947\u091c \u091d\u0941\u0915\u093e\u0935 \u092a\u0930 \u0938\u0921\u093c\u0915 \u092a\u093e\u0930 \u0928\u0939\u0940\u0902 \u0915\u0930\u0928\u0940 \u091a\u093e\u0939\u093f\u090f \u092f\u093e \u090f\u0915 \u092c\u0902\u0926 \u0935\u093e\u0939\u0928 \u0915\u0947 \u092c\u0939\u0941\u0924 \u0915\u0930\u0940\u092c\u0964 \u0915\u094d\u092f\u0942\u0902 ", "\u0932\u092e\u094d\u092c\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0906\u0928\u0947 \u0935\u093e\u0932\u0947 \u0905\u0928\u094d\u092f \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0921\u094d\u0930\u093e\u0907\u0935\u0930, \u0938\u0921\u093c\u0915 \u092a\u093e\u0930 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0915\u094b \u0928\u0939\u0940\u0902 \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "\u0905\u0928\u094d\u092f \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0905\u0938\u0941\u0935\u093f\u0927\u093e", "\u0905\u0928\u094d\u092f \u0938\u0921\u093c\u0915 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e\u0913\u0902 \u0915\u094b \u0905\u0938\u0941\u0935\u093f\u0927\u093e", "\u0932\u092e\u094d\u092c\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0906\u0928\u0947 \u0935\u093e\u0932\u0947 \u0905\u0928\u094d\u092f \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0921\u094d\u0930\u093e\u0907\u0935\u0930, \u0938\u0921\u093c\u0915 \u092a\u093e\u0930 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0915\u094b \u0928\u0939\u0940\u0902 \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor50 = new Task_QueConstructor(61, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "2 \u092e\u0940\u091f\u0930 \u0938\u0947 \u0905\u0927\u093f\u0915 \u091a\u094c\u0921\u093c\u093e\u0908 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f \u0928\u0939\u0940\u0902", "\u0938\u094d\u092a\u0940\u0921 \u0938\u0940\u092e\u093e 2 \u0915\u093f\u092e\u0940 / \u0918\u0902\u091f\u093e", "2 \u092e\u0940\u091f\u0930 \u0938\u0947 \u0905\u0927\u093f\u0915 \u091a\u094c\u0921\u093c\u093e\u0908 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f \u0928\u0939\u0940\u0902", "2 \u092e\u0940\u091f\u0930 \u090a\u0902\u091a\u093e\u0908 \u0938\u0947 \u0905\u0927\u093f\u0915 \u0939\u094b\u0928\u0947 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f \u0928\u0939\u0940\u0902", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor51 = new Task_QueConstructor(62, "\u090f\u0915 \u0928\u093f\u091c\u0940 \u0935\u093e\u0939\u0928 \u0915\u0947 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0939\u0948\u0902", "\u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930\u0964, \u092c\u0940\u092e\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930 \u0915\u0930 \u091f\u094b\u0915\u0928, \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938", "\u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930, \u091c\u0940.\u0938\u0940.\u0906\u0930., \u092c\u0940\u092e\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930", "\u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930\u0964, \u092c\u0940\u092e\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930 \u0915\u0930 \u091f\u094b\u0915\u0928, \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938", "\u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930, \u092a\u0930\u092e\u093f\u091f, \u091f\u094d\u0930\u093f\u092a \u0936\u0940\u091f", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor52 = new Task_QueConstructor(63, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "3.5 \u092e\u0940\u091f\u0930 \u0938\u0947 \u0905\u0927\u093f\u0915 \u090a\u0902\u091a\u093e\u0908 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0935\u0947\u0936", "\u0915\u0947\u0935\u0932 3.5 \u092e\u0940\u091f\u0930 \u090a\u0901\u091a\u093e\u0908 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0935\u0947\u0936", "3.5 \u092e\u0940\u091f\u0930 \u0938\u0947 \u0905\u0927\u093f\u0915 \u0915\u0940 \u091a\u094c\u0921\u093c\u093e\u0908 \u0935\u093e\u0932\u093e \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0935\u0947\u0936", "3.5 \u092e\u0940\u091f\u0930 \u0938\u0947 \u0905\u0927\u093f\u0915 \u090a\u0902\u091a\u093e\u0908 \u0935\u093e\u0932\u0947 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0935\u0947\u0936", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor53 = new Task_QueConstructor(64, "\u091c\u093f\u0938 \u0938\u0921\u093c\u0915 \u092a\u0930 \u0906\u092a \u091c\u093e \u0930\u0939\u0947 \u0939\u0948\u0902, \u0909\u0938\u0915\u0947 \u092c\u093e\u0908\u0902 \u0913\u0930 \u090f\u0915 \u0938\u0921\u093c\u0915 \u0915\u0947 \u092e\u0941\u0921\u093c\u0924\u0947 \u0939\u0941\u090f, \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u092c\u093e\u0908\u0902 \u0924\u0930\u092b \u0938\u0902\u0915\u0947\u0924 \u0926\u093f\u0916\u093e\u090f\u0902, \u0938\u0921\u093c\u0915 \u0915\u0947 \u092c\u093e\u0908\u0902 \u0913\u0930 \u0935\u093e\u0939\u0928 \u0930\u0916\u0947\u0902 \u0914\u0930 \u092c\u093e\u090f\u0902 \u0913\u0930 \u091c\u093e\u090f\u0902", "\u092c\u093e\u090f\u0902 \u091f\u0930\u094d\u0928 \u0938\u093f\u0917\u094d\u0928\u0932 \u0926\u093f\u0916\u093e\u090f\u0902, \u0915\u0947\u0902\u0926\u094d\u0930 \u092a\u0930 \u091c\u093e\u090f\u0902 \u0914\u0930 \u092c\u093e\u0908\u0902 \u0913\u0930 \u091c\u093e\u090f\u0902", "\u0927\u094d\u0935\u0928\u093f \u0939\u0949\u0930\u094d\u0928 \u0914\u0930 \u092c\u093e\u0908\u0902 \u0913\u0930 \u0918\u0941\u092e\u093e\u090f\u0902", "\u092c\u093e\u0908\u0902 \u0924\u0930\u092b \u0938\u0902\u0915\u0947\u0924 \u0926\u093f\u0916\u093e\u090f\u0902, \u0938\u0921\u093c\u0915 \u0915\u0947 \u092c\u093e\u0908\u0902 \u0913\u0930 \u0935\u093e\u0939\u0928 \u0930\u0916\u0947\u0902 \u0914\u0930 \u092c\u093e\u090f\u0902 \u0913\u0930 \u091c\u093e\u090f\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor54 = new Task_QueConstructor(65, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0930\u0941\u0915\u0928\u093e \u092f\u093e \u0916\u0921\u093c\u0947 \u0939\u094b\u0928\u093e \u0928\u093f\u0937\u0947\u0927", "\u0930\u0941\u0915\u0947\u0902", "\u0930\u0941\u0915\u0928\u093e \u092f\u093e \u0916\u0921\u093c\u0947 \u0939\u094b\u0928\u093e \u0928\u093f\u0937\u0947\u0927", "\u0938\u0902\u0917\u092e", "photo");
            Task_QueConstructor m_rtoTaskQueConstructor55 = new Task_QueConstructor(66, "\u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930 \u0915\u0947 \u0924\u0939\u0924 \u092a\u0940\u092f\u0942\u0938\u0940\u0938\u0940 \u092a\u094d\u0930\u0926\u0942\u0937\u0923 \u0915\u0940 \u0935\u0948\u0927\u0924\u093e", "6 \u092e\u0939\u0940\u0928\u0947", "6 \u092e\u0939\u0940\u0928\u0947", "\u090f\u0915 \u0938\u093e\u0932", "\u0926\u094b \u0938\u093e\u0932", "nophoto");
