            Task_QueConstructor m_rtoTaskQueConstructor114 = new Task_QueConstructor(125, "\u092e\u094b\u091f\u0930 \u0938\u093e\u0907\u0915\u093f\u0932 \u092a\u0930 \u092a\u093f\u0932\u093f\u092f\u0928 \u0930\u093e\u0907\u0921\u0930 \u0932\u0947 \u091c\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "\u0935\u093e\u0939\u0928 \u0915\u094b \u092a\u0948\u0930 \u0915\u0940 \u0906\u0930\u093e\u092e, \u0939\u093e\u0925 \u092a\u0915\u0921\u093c \u0914\u0930 \u0938\u093e\u0921\u093c\u0940 \u0917\u093e\u0930\u094d\u0921 \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u093f\u092f\u093e \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0935\u093e\u0939\u0928 \u0915\u094b \u092a\u0948\u0930 \u0915\u0940 \u0906\u0930\u093e\u092e, \u0939\u093e\u0925 \u092a\u0915\u0921\u093c \u0914\u0930 \u0938\u093e\u0921\u093c\u0940 \u0917\u093e\u0930\u094d\u0921 \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u093f\u092f\u093e \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0935\u093e\u0939\u0928 \u0915\u094b \u0938\u093e\u0907\u0921 \u0915\u093e\u0930 \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u093f\u092f\u093e \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0935\u093e\u0939\u0928 \u0915\u094b \u0930\u093f\u092f\u0930 \u0935\u094d\u092f\u0942 \u092e\u093f\u0930\u0930 \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u0926\u093e\u0928 \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "nophoto");
