            Task_QueConstructor m_rtoTaskQueConstructor154 = new Task_QueConstructor(165, "\u0938\u094d\u091f\u0949\u092a \u0932\u093e\u0907\u0928 \u0938\u0947 \u0915\u094d\u092f\u093e \u092e\u0924\u0932\u092c \u0939\u0948", "\u0938\u0921\u093c\u0915 \u091c\u0902\u0915\u094d\u0936\u0928 \u092f\u093e \u092a\u0948\u0926\u0932 \u092f\u093e\u0924\u094d\u0930\u0940 \u0915\u094d\u0930\u0949\u0938\u093f\u0902\u0917 \u0915\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u092a\u0930 \u0938\u092b\u0947\u0926 \u092f\u093e \u092a\u0940\u0932\u0947 \u0930\u0902\u0917 \u0915\u0940 \u090f\u0915 \u092a\u0902\u0915\u094d\u0924\u093f", "\u0938\u0921\u093c\u0915 \u091c\u0902\u0915\u094d\u0936\u0928 \u092f\u093e \u092a\u0948\u0926\u0932 \u092f\u093e\u0924\u094d\u0930\u0940 \u0915\u094d\u0930\u0949\u0938\u093f\u0902\u0917 \u0915\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u092a\u0930 \u0938\u092b\u0947\u0926 \u092f\u093e \u092a\u0940\u0932\u0947 \u0930\u0902\u0917 \u0915\u0940 \u090f\u0915 \u092a\u0902\u0915\u094d\u0924\u093f", "\u092a\u0940\u0932\u0947 \u0930\u0902\u0917 \u092e\u0947\u0902 \u0938\u0921\u093c\u0915 \u0915\u0947 \u0915\u0947\u0902\u0926\u094d\u0930 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0924\u0948\u092f\u093e\u0930 \u0915\u0940 \u0917\u0908 \u0930\u0947\u0916\u093e", "\u0938\u0921\u093c\u0915 \u0915\u0947 \u0915\u0947\u0902\u0926\u094d\u0930 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u091f\u0942\u091f\u0940 \u0939\u0941\u0908 \u0938\u092b\u0947\u0926 \u0930\u0947\u0916\u093e", "nophoto");
