            Task_QueConstructor m_rtoTaskQueConstructor176 = new Task_QueConstructor(187, "\u0926\u094b\u092a\u0939\u093f\u092f\u093e \u0935\u093e\u0939\u0928 \u091a\u0932\u093e\u0928\u0947 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u0939\u0947\u0932\u092e\u0947\u091f \u092a\u0939\u0928\u0928\u093e \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948 \u0915\u094d\u092f\u094b\u0902\u0915\u093f", "\u092f\u0939 \u0906\u092a\u0915\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0915\u0947 \u0932\u093f\u090f \u0939\u0948", "\u092f\u0939 \u0906\u092a\u0915\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0915\u0947 \u0932\u093f\u090f \u0939\u0948", "\u0935\u0939 \u092a\u0941\u0932\u093f\u0938 \u0926\u094d\u0935\u093e\u0930\u093e \u092a\u0915\u0921\u093c\u093e \u091c\u093e\u090f\u0917\u093e", "\u0938\u0921\u093c\u0915 \u092a\u0930 \u0938\u092e\u093e\u0928\u0924\u093e \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor177 = new Task_QueConstructor(188, "\u091c\u092c \u0906\u092a \u0905\u092a\u0928\u0947 \u0935\u093e\u0939\u0928 \u0915\u0947 \u0939\u0949\u0930\u094d\u0928 \u0915\u094b \u0927\u094d\u0935\u0928\u093f \u0915\u092c \u0926\u0947\u0902\u0917\u0947?", "\u0905\u092a\u0928\u0940 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f \u0915\u0947 \u0905\u0928\u094d\u092f \u0921\u094d\u0930\u093e\u0907\u0935\u0930 \u0915\u094b \u091a\u0947\u0924\u093e\u0935\u0928\u0940 \u0926\u0947\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "\u0905\u0928\u094d\u092f \u0935\u093e\u0939\u0928 \u0938\u0947 \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u0924\u0947 \u0938\u092e\u092f", "\u0905\u092a\u0928\u0940 \u0909\u092a\u0938\u094d\u0925\u093f\u0924\u093f \u0915\u0947 \u0905\u0928\u094d\u092f \u0921\u094d\u0930\u093e\u0907\u0935\u0930 \u0915\u094b \u091a\u0947\u0924\u093e\u0935\u0928\u0940 \u0926\u0947\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "\u090f\u0915 \u0926\u094b\u0938\u094d\u0924 \u0915\u093e \u0927\u094d\u092f\u093e\u0928 \u0906\u0915\u0930\u094d\u0937\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor178 = new Task_QueConstructor(189, "\u0906\u092a \u090f\u0915 \u092c\u0938 \u0915\u0947 \u092a\u0940\u091b\u0947 \u0939\u0948\u0902 \u091c\u094b \u092f\u093e\u0924\u094d\u0930\u093f\u092f\u094b\u0902 \u0915\u094b \u092a\u093f\u0915\u0905\u092a \u092f\u093e \u0921\u094d\u0930\u0949\u092a \u0915\u0930 \u0930\u0939\u093e \u0939\u0948, \u0924\u094b \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0927\u0948\u0930\u094d\u092f \u0938\u0947 \u092a\u0940\u091b\u0947 \u0930\u0941\u0915\u094b", "\u0927\u0948\u0930\u094d\u092f \u0938\u0947 \u092a\u0940\u091b\u0947 \u0930\u0941\u0915\u094b", "\u092c\u093e\u090f\u0902 \u0938\u0947 \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u094b", "\u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0938\u0947 \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u094b", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor179 = new Task_QueConstructor(190, "\u0906\u092a \u0930\u093e\u0924 \u092e\u0947\u0902 \u090f\u0915 \u0915\u093e\u0930 \u0938\u0947 \u0906\u0917\u0947 \u0928\u093f\u0915\u0932 \u0930\u0939\u0947 \u0939\u0948\u0902\u0964 \u0906\u092a\u0915\u094b \u092f\u0939 \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0915\u0930\u0928\u093e \u0939\u094b\u0917\u093e \u0915\u093f", "\u0906\u092a \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u0947\u0921\u0932\u093e\u0907\u091f \u0915\u094b \u092b\u094d\u0932\u0948\u0936 \u0915\u0930\u0947\u0902", "\u0906\u092a \u0905\u0928\u094d\u092f \u0938\u0921\u093c\u0915 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e\u0913\u0902 \u0915\u094b \u091a\u0915\u093e\u091a\u094c\u0902\u0927 \u0928\u0939\u0940\u0902 \u0915\u0930\u0947\u0902", "\u0906\u092a \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0939\u0947\u0921\u0932\u093e\u0907\u091f \u0915\u094b \u092b\u094d\u0932\u0948\u0936 \u0915\u0930\u0947\u0902", "\u0906\u092a\u0915\u0947 \u0930\u093f\u092f\u0930 \u0915\u094b\u0939\u0930\u0947 \u0932\u093e\u0907\u091f\u094d\u0938 \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor180 = new Task_QueConstructor(191, "\u090f\u0915 \u091a\u092e\u0915\u0924\u0940 \u092a\u0940\u0932\u0947 \u0930\u0902\u0917 \u0915\u093e \u0938\u0902\u0915\u0947\u0924 \u0924\u092c \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f \u0939\u0948, \u091c\u092c", "\u0906\u092a \u0927\u0940\u092e\u093e \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u092c\u0930\u0924\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u091f\u094d\u0930\u0948\u092b\u093f\u0915 \u0932\u093e\u0907\u091f \u0915\u093e\u092e \u0928\u0939\u0940\u0902 \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902", "\u0906\u092a \u0927\u0940\u092e\u093e \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u092c\u0930\u0924\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u092a\u0941\u0930\u0941\u0937 \u0915\u093e\u092e \u092a\u0930 \u0939\u0948\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor181 = new Task_QueConstructor(192, "\u0906\u092a \u091c\u0947\u092c\u094d\u0930\u093e \u0915\u094d\u0930\u0949\u0938\u093f\u0902\u0917 \u092a\u0930 \u092a\u093e\u0930 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0947 \u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0935\u093e\u0939\u0928 \u0930\u094b\u0915\u0924\u0947 \u0939\u0948\u0902 \u0935\u0947 \u0915\u094d\u0930\u0949\u0938 \u0915\u0930\u0928\u093e \u0936\u0941\u0930\u0942 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902, \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0927\u0940\u0930\u091c \u0914\u0930 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0947\u0902", "\u0905\u092a\u0928\u093e \u0939\u0949\u0930\u094d\u0928 \u0927\u094d\u0935\u0928\u093f \u0915\u0930\u0947\u0902", "\u0927\u0940\u0930\u091c \u0914\u0930 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0947\u0902", "\u0935\u093e\u0939\u0928 \u0921\u094d\u0930\u093e\u0907\u0935 \u0915\u0930\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor182 = new Task_QueConstructor(193, "\u0906\u092a\u0915\u094b \u092a\u093e\u0930\u094d\u0915 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0939\u0948", "\u0907\u0928 \u0926\u094b \u0935\u093f\u0915\u0932\u094d\u092a\u094b\u0902 \u092e\u0947\u0902 \u0938\u0947 \u0915\u094b\u0908 \u092d\u0940 \u0928\u0939\u0940\u0902", "\u090f\u0915 \u092b\u0941\u091f\u092a\u093e\u0925 \u092a\u0930", "\u0905\u0938\u094d\u092a\u0924\u093e\u0932 \u0915\u0947 \u0938\u093e\u092e\u0928\u0947", "\u0907\u0928 \u0926\u094b \u0935\u093f\u0915\u0932\u094d\u092a\u094b\u0902 \u092e\u0947\u0902 \u0938\u0947 \u0915\u094b\u0908 \u092d\u0940 \u0928\u0939\u0940\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor183 = new Task_QueConstructor(194, "\u0927\u0942\u092e\u093f\u0932 \u0938\u094d\u0925\u093f\u0924\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u090f\u0915 \u0909\u091a\u094d\u091a \u092c\u0940\u092e \u092a\u094d\u0930\u0915\u093e\u0936", "\u092c\u0941\u0930\u093e \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u092f\u0939 \u0935\u093e\u092a\u0938 \u092a\u094d\u0930\u0924\u093f\u092c\u093f\u0902\u092c\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u091a\u0915\u093e\u091a\u094c\u0902\u0927 \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948", "\u0905\u091a\u094d\u091b\u093e \u0939\u0948 \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u0906\u092a \u0905\u0927\u093f\u0915 \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "\u092c\u0941\u0930\u093e \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u092f\u0939 \u0935\u093e\u092a\u0938 \u092a\u094d\u0930\u0924\u093f\u092c\u093f\u0902\u092c\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u091a\u0915\u093e\u091a\u094c\u0902\u0927 \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948", "\u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0915\u0930\u0947\u0902 \u0915\u093f \u0926\u0942\u0938\u0930\u094b\u0902 \u0915\u094b \u0906\u092a \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor184 = new Task_QueConstructor(195, "\u091c\u092c \u0915\u094b\u0908 \u0915\u094d\u0930\u0949\u0938\u093f\u0902\u0917 \u0906 \u0930\u0939\u093e \u0939\u0948 \u091c\u0939\u093e\u0902 \u0906\u092a \u0938\u0940\u0927\u0947 \u091c\u093e\u0924\u0947 \u0939\u0948\u0902", "\u0932\u0947\u0928\u094b\u0902 \u0915\u094b \u0915\u092e \u0938\u0947 \u0915\u092e 50 \u092e\u0940\u091f\u0930 \u0906\u0917\u0947 \u092e\u0927\u094d\u092f \u0932\u0947\u0928 \u092e\u0947\u0902 \u092c\u0926\u0932\u0947\u0902", "\u0932\u0947\u0928 \u0915\u094b \u0938\u0939\u0940 \u0932\u0947\u0928 \u092e\u0947\u0902 \u092c\u0926\u0932\u0947\u0902", "\u0932\u0947\u0928\u094b\u0902 \u0915\u094b \u0915\u092e \u0938\u0947 \u0915\u092e 50 \u092e\u0940\u091f\u0930 \u0906\u0917\u0947 \u092e\u0927\u094d\u092f \u0932\u0947\u0928 \u092e\u0947\u0902 \u092c\u0926\u0932\u0947\u0902", "\u0915\u094d\u0930\u0949\u0938\u093f\u0902\u0917 \u092a\u0930 \u092e\u0927\u094d\u092f \u0932\u0947\u0928 \u092e\u0947\u0902 \u0932\u0947\u0928 \u092c\u0926\u0932\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor185 = new Task_QueConstructor(196, "\u0906\u092a \u0917\u093e\u0921\u093c\u0940 \u091a\u0932\u093e \u0930\u0939\u0947 \u0939\u0948\u0902, \u090f\u0915 \u0935\u093e\u0939\u0928 \u091a\u092e\u0915\u0924\u0947 \u0939\u0947\u0921\u0932\u093e\u0907\u091f \u0915\u0947 \u0938\u093e\u0925 \u091c\u0932\u094d\u0926\u0940 \u0938\u0947 \u092a\u0940\u091b\u0947 \u0906\u0924\u093e \u0939\u0948, \u0906\u092a\u0915\u094b", "\u092f\u0926\u093f \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0939\u094b \u0924\u094b \u0935\u093e\u0939\u0928 \u0915\u094b \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0926\u0947\u0902", "\u0906\u092a\u0915\u0947 \u092a\u0940\u091b\u0947 \u0905\u0902\u0924\u0930 \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u0947 \u092e\u0947\u0902 \u0924\u0947\u091c\u0940 \u092c\u0922\u093c\u093e\u090f\u0902", "\u0905\u092a\u0928\u0947 \u092c\u094d\u0930\u0947\u0915\u0932\u093e\u0908\u091f\u094d\u0938 \u0915\u094b \u0926\u093f\u0916\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092c\u094d\u0930\u0947\u0915 \u0938\u094d\u092a\u0930\u094d\u0936 \u0915\u0930\u0947\u0902", "\u092f\u0926\u093f \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0939\u094b \u0924\u094b \u0935\u093e\u0939\u0928 \u0915\u094b \u0906\u0917\u0947 \u0928\u093f\u0915\u0932\u0928\u0947 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0926\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor186 = new Task_QueConstructor(197, "\u0926\u093f\u0928 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u0906\u092a\u0915\u094b \u0932\u094b \u092c\u0940\u092e \u0939\u0947\u0921\u0932\u093e\u0907\u091f \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u092c \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0916\u0930\u093e\u092c \u0926\u0943\u0936\u094d\u092f\u0924\u093e \u0914\u0930 \u0930\u093e\u091c\u092e\u093e\u0930\u094d\u0917\u094b\u0902 \u092e\u0947\u0902", "\u0916\u0930\u093e\u092c \u0926\u0943\u0936\u094d\u092f\u0924\u093e \u0914\u0930 \u0930\u093e\u091c\u092e\u093e\u0930\u094d\u0917\u094b\u0902 \u092e\u0947\u0902", "\u0926\u0947\u0936 \u0915\u0940 \u0938\u0921\u093c\u0915\u094b\u0902 \u092a\u0930", "\u0938\u0902\u0915\u0940\u0930\u094d\u0923 \u0938\u0921\u093c\u0915 \u0915\u0947 \u0938\u093e\u0925", "nophoto");
