            Task_QueConstructor m_rtoTaskQueConstructor188 = new Task_QueConstructor(199, "\u092f\u0939 \u091a\u093f\u0928\u094d\u0939 \u0915\u094d\u092f\u093e \u0938\u0902\u0915\u0947\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0926\u094b\u0928\u094b\u0902 \u0938\u0921\u093c\u0915\u0947\u0902 \u0928\u093f\u0937\u093f\u0926\u094d\u0927 \u0939\u0948\u0902", "\u092a\u094d\u0930\u0935\u0947\u0936 \u0928\u093f\u0937\u0947\u0927", "\u0926\u094b\u0928\u094b\u0902 \u0938\u0921\u093c\u0915\u0947\u0902 \u0928\u093f\u0937\u093f\u0926\u094d\u0927 \u0939\u0948\u0902", "\u0906\u0917\u0947 \u0916\u0924\u0930\u093e \u0939\u0948", "photo");
