            Task_QueConstructor m_rtoTaskQueConstructor240 = new Task_QueConstructor(252, "\u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f, \u0906\u092a\u0915\u094b \u0935\u0947 \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u0947 \u0915\u094b \u092c\u0924\u093e\u0924\u0947 \u0939\u0948\u0902", "\u0938\u094d\u092a\u0937\u094d\u091f \u0926\u093f\u0928 \u0915\u0947 \u0909\u091c\u093e\u0932\u0947 \u092e\u0947\u0902 25 \u092e\u0940\u091f\u0930 \u0915\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0915\u093e\u0930 \u0915\u0940 \u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u0938\u0902\u0916\u094d\u092f\u093e \u092a\u094d\u0932\u0947\u091f \u092a\u0922\u093c\u0947\u0902", "\u0938\u094d\u092a\u0937\u094d\u091f \u0926\u093f\u0928 \u0915\u0947 \u0909\u091c\u093e\u0932\u0947 \u092e\u0947\u0902 25 \u092e\u0940\u091f\u0930 \u0915\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0915\u093e\u0930 \u0915\u0940 \u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u0938\u0902\u0916\u094d\u092f\u093e \u092a\u094d\u0932\u0947\u091f \u092a\u0922\u093c\u0947\u0902", "\u0938\u094d\u092a\u0937\u094d\u091f \u0926\u093f\u0928 \u0915\u0947 \u0909\u091c\u093e\u0932\u0947 \u092e\u0947\u0902 10 \u092e\u0940\u091f\u0930 \u0915\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0915\u093e\u0930 \u0915\u0940 \u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u0938\u0902\u0916\u094d\u092f\u093e \u092a\u094d\u0932\u0947\u091f \u092a\u0922\u093c\u0947\u0902", "\u0938\u094d\u092a\u0937\u094d\u091f \u0926\u093f\u0928 \u0915\u0947 \u0909\u091c\u093e\u0932\u0947 \u092e\u0947\u0902 15 \u092e\u0940\u091f\u0930 \u0915\u0940 \u0926\u0942\u0930\u0940 \u092a\u0930 \u0915\u093e\u0930 \u0915\u0940 \u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u0938\u0902\u0916\u094d\u092f\u093e \u092a\u094d\u0932\u0947\u091f \u092a\u0922\u093c\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor241 = new Task_QueConstructor(253, "\u0936\u093f\u0915\u094d\u0937\u093e\u0930\u094d\u0925\u093f\u092f\u094b\u0902 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0915\u0947 \u0938\u093e\u0925 \u092e\u094b\u091f\u0930 \u0938\u093e\u0907\u0915\u093f\u0932 \u0915\u0940 \u0938\u0935\u093e\u0930\u0940 \u0915\u0930\u0924\u0947 \u0938\u092e\u092f \u0906\u092a\u0915\u094b \u0915\u093f\u0938\u0915\u0947 \u0938\u093e\u0925 \u0938\u0935\u093e\u0930\u0940 \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0915\u0947\u0935\u0932 \u0906\u092a\u0915\u0947 \u0938\u093e\u0925 \u090f\u0915 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0927\u093e\u0930\u0915 \u092a\u093f\u0932\u094d\u0932\u093f\u092f\u0928 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0935\u093e\u0930\u0940 \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0915\u0947\u0935\u0932 \u0926\u093f\u0928 \u0915\u0940 \u0930\u094b\u0936\u0928\u0940 \u092e\u0947\u0902", "\u0915\u0947\u0935\u0932 \u0915\u092e \u092f\u093e\u0924\u093e\u092f\u093e\u0924 \u0935\u093e\u0932\u0947 \u0938\u0921\u093c\u0915\u094b\u0902 \u092a\u0930", "\u0915\u0947\u0935\u0932 \u0906\u092a\u0915\u0947 \u0938\u093e\u0925 \u090f\u0915 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0927\u093e\u0930\u0915 \u092a\u093f\u0932\u094d\u0932\u093f\u092f\u0928 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0935\u093e\u0930\u0940 \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor242 = new Task_QueConstructor(254, "\u0906\u0930 \u091f\u0940 \u0913 \u0938\u0947 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u090f\u0915 \u0936\u093f\u0915\u094d\u0937\u093e\u0930\u094d\u0925\u0940 \u0915\u093e \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092e\u0939\u093e\u0930\u093e\u0937\u094d\u091f\u094d\u0930 \u0915\u093e\u0930\u094d\u092f\u093e\u0932\u092f \u092e\u0947\u0902 \u0935\u0948\u0927 \u0939\u0948", "\u0938\u0930\u094d\u0935\u0924\u094d\u0930 \u0907\u0902\u0921\u093f\u092f\u093e", "\u0906\u0930\u091f\u0940\u0913 \u0915\u0947 \u0905\u0927\u093f\u0915\u093e\u0930 \u0915\u094d\u0937\u0947\u0924\u094d\u0930 \u092e\u0947\u0902 \u0939\u0940 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e", "\u0938\u0930\u094d\u0935\u0924\u094d\u0930 \u092e\u0939\u093e\u0930\u093e\u0937\u094d\u091f\u094d\u0930", "\u0938\u0930\u094d\u0935\u0924\u094d\u0930 \u0907\u0902\u0921\u093f\u092f\u093e", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor243 = new Task_QueConstructor(255, "\u092f\u0926\u093f \u0906\u092a\u0915\u0947 \u092a\u093e\u0938 \u090f\u0915 \u0936\u093f\u0915\u094d\u0937\u093e\u0930\u094d\u0925\u0940 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0939\u0948 \u091c\u094b \u092e\u094b\u091f\u0930 \u0938\u093e\u0907\u0915\u093f\u0932 \u091a\u0932\u093e\u0924\u093e \u0939\u0948", "\u0915\u0947\u0935\u0932 \u0906\u092a\u0915\u0947 \u0938\u093e\u0925 \u090f\u0915 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0927\u093e\u0930\u0915 \u092a\u093f\u0932\u094d\u0932\u093f\u092f\u0928 \u0915\u0947 \u0938\u093e\u0925 \u0921\u094d\u0930\u093e\u0907\u0935 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "\u0906\u092a \u0926\u093f\u0928 \u092e\u0947\u0902 \u0915\u092e \u091f\u094d\u0930\u0948\u092b\u093f\u0915 \u0938\u0921\u093c\u0915 \u092a\u0930 \u0938\u0935\u093e\u0930\u0940 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "\u092a\u093f\u0932\u093f\u092f\u0928 \u0930\u093e\u0907\u0921\u0930 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0928\u0939\u0940\u0902 \u0939\u0948", "\u0915\u0947\u0935\u0932 \u0906\u092a\u0915\u0947 \u0938\u093e\u0925 \u090f\u0915 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0927\u093e\u0930\u0915 \u092a\u093f\u0932\u094d\u0932\u093f\u092f\u0928 \u0915\u0947 \u0938\u093e\u0925 \u0921\u094d\u0930\u093e\u0907\u0935 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor244 = new Task_QueConstructor(256, "\u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u0936\u093f\u0915\u094d\u0937\u093e\u0930\u094d\u0925\u093f\u092f\u094b\u0902 \u0932\u093e\u0907\u0938\u0947\u0902\u0938\u0927\u093e\u0930\u0915 \u0915\u0947 \u0932\u093f\u090f '\u090f\u0932' \u092c\u094b\u0930\u094d\u0921 \u0915\u0940 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928\u0940", "\u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f", "\u091c\u093c\u0930\u0942\u0930\u0940", "\u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f", "\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor245 = new Task_QueConstructor(257, "\u090f\u0915 \u092e\u094b\u091f\u0930 \u0935\u093e\u0939\u0928 (\u0915\u093e\u0930 \u091c\u0940\u092a \u0907\u0924\u094d\u092f\u093e\u0926\u093f) \u0915\u094b \u091a\u0932\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f, \u0906\u092a\u0915\u0940 \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u0906\u092f\u0941", "\u0905\u0920\u093e\u0930\u0939 \u0935\u0930\u094d\u0937", "16 \u0935\u0930\u094d\u0937", "\u0905\u0920\u093e\u0930\u0939 \u0935\u0930\u094d\u0937", "20 \u0938\u093e\u0932", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor246 = new Task_QueConstructor(258, "\u092e\u094b\u091f\u0930 \u0938\u093e\u0907\u0915\u093f\u0932 \u092f\u093e \u0917\u093e\u0921\u093c\u0940 \u091a\u0932\u093e\u0924\u0947 \u0938\u092e\u092f \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0932\u0947 \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092c\u0940\u092e\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930 \u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u0914\u0930 \u092a\u0940\u092f\u0942\u0938\u0940", "\u0915\u0947\u0935\u0932 \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938", "\u0915\u0947\u0935\u0932 \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0914\u0930 \u092a\u0940\u092f\u0942\u0938\u0940", "\u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092c\u0940\u092e\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930 \u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u0914\u0930 \u092a\u0940\u092f\u0942\u0938\u0940", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor247 = new Task_QueConstructor(259, "\u0905\u092a\u0928\u0947 \u0938\u092e\u092f \u0938\u0940\u092e\u093e \u0938\u092e\u093e\u092a\u094d\u0924 \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0915\u094b \u0928\u0935\u0940\u0928\u0940\u0915\u0943\u0924 \u0915\u0930\u0928\u0947 \u0915\u093e \u0905\u0928\u0941\u0917\u094d\u0930\u0939 \u0905\u0935\u0927\u093f \u0939\u0948", "\u0924\u0940\u0938 \u0926\u093f\u0928", "\u0924\u0940\u0938 \u0926\u093f\u0928", "60 \u0926\u093f\u0928", "\u0915\u094b\u0908 \u0905\u0928\u0941\u0917\u094d\u0930\u0939 \u0905\u0935\u0927\u093f \u0928\u0939\u0940\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor248 = new Task_QueConstructor(260, "\u0915\u094d\u092f\u093e \u0915\u094b\u0908 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0928\u093f\u0932\u0902\u092c\u093f\u0924 \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0915\u0947 \u0938\u093e\u0925 \u0921\u094d\u0930\u093e\u0907\u0935 \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948?", "\u0915\u092d\u0940 \u0928\u0939\u0940\u0901", "\u0915\u0947\u0935\u0932 \u0906\u092a\u093e\u0924\u0915\u093e\u0932 \u092e\u0947\u0902", "\u0915\u0947\u0935\u0932 \u091c\u092c \u0915\u094b\u0908 \u0932\u093e\u0907\u0938\u0947\u0902\u0938\u0927\u093e\u0930\u0915 \u0909\u0938\u0915\u0947 \u0938\u093e\u0925 \u0939\u094b\u0924\u093e \u0939\u0948", "\u0915\u092d\u0940 \u0928\u0939\u0940\u0901", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor249 = new Task_QueConstructor(261, "\u092f\u0926\u093f \u0906\u092a\u0915\u0947 \u092a\u093e\u0938 \u0915\u093e\u0930 \u091a\u0932\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0939\u0948, \u0924\u094b \u0906\u092a \u0921\u094d\u0930\u093e\u0907\u0935 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902?", "\u0915\u0947\u0935\u0932 \u0915\u093e\u0930", "\u092e\u094b\u091f\u0930 \u0938\u093e\u0907\u0915\u093f\u0932 \u0914\u0930 \u0915\u093e\u0930", "\u0915\u0947\u0935\u0932 \u0915\u093e\u0930", "\u092d\u093e\u0930\u0940 \u0935\u093e\u0939\u0928\u094b\u0902 \u0915\u0947 \u0905\u0932\u093e\u0935\u093e", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor250 = new Task_QueConstructor(262, "\u092e\u094b\u091f\u0930 \u0938\u093e\u0907\u0915\u093f\u0932 \u0914\u0930 \u0915\u093e\u0930 \u0915\u094b \u091a\u0932\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0915\u0940 \u0935\u0948\u0927\u0924\u093e \u0915\u094d\u092f\u093e \u0939\u0948?", "20 \u0935\u0930\u094d\u0937 \u092f\u093e 50 \u0935\u0930\u094d\u0937 \u0915\u0940 \u0909\u092e\u094d\u0930 \u0924\u0915, \u091c\u094b \u092d\u0940 \u0915\u092e \u0939\u094b", "5 \u0935\u0930\u094d\u0937", "10 \u0938\u093e\u0932", "20 \u0935\u0930\u094d\u0937 \u092f\u093e 50 \u0935\u0930\u094d\u0937 \u0915\u0940 \u0909\u092e\u094d\u0930 \u0924\u0915, \u091c\u094b \u092d\u0940 \u0915\u092e \u0939\u094b", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor251 = new Task_QueConstructor(263, "\u0906\u092a\u0915\u094b \u0921\u094d\u0930\u093e\u0907\u0935\u093f\u0902\u0917 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092a\u0930 \u0905\u092a\u0928\u093e \u092c\u0926\u0932\u093e \u092a\u0924\u093e \u0915\u092c \u0906\u0930\u091f\u0940\u0913 \u092e\u0947\u0902 \u092a\u0924\u093e \u0938\u0942\u091a\u093f\u0924 \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "14 \u0926\u093f\u0928 \u0924\u0915", "\u0926\u0938 \u0926\u093f\u0928 \u0924\u0915", "14 \u0926\u093f\u0928 \u0924\u0915", "\u0924\u0940\u0938 \u0926\u093f\u0928 \u0924\u0915", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor252 = new Task_QueConstructor(264, "\u091c\u093c\u0947\u092c\u0930\u093e \u0915\u094d\u0930\u0949\u0938\u093f\u0902\u0917 \u092a\u0930 \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f?", "\u0930\u0941\u0915\u094b \u0914\u0930 \u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0915\u094b \u092a\u093e\u0930 \u0915\u0930\u0928\u0947 \u0926\u0947\u0902", "\u090f\u0915 \u0939\u0940 \u0917\u0924\u093f \u092a\u0930 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902", "\u0930\u0941\u0915\u094b \u0914\u0930 \u092a\u0948\u0926\u0932 \u091a\u0932\u0928\u0947 \u0935\u093e\u0932\u094b\u0902 \u0915\u094b \u092a\u093e\u0930 \u0915\u0930\u0928\u0947 \u0926\u0947\u0902", "\u0917\u0924\u093f \u0915\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u0938\u0947 \u091a\u0932\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor253 = new Task_QueConstructor(265, "\u090f\u0915 \u091a\u094c\u0930\u093e\u0939\u0947 / \u0926\u094d\u0935\u0940\u092a \u092e\u0947\u0902 \u092a\u094d\u0930\u0935\u0947\u0936 \u0915\u0930\u0924\u0947 \u0938\u092e\u092f \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f?", "\u092a\u094d\u0930\u0935\u0947\u0936 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0909\u0928 \u0932\u094b\u0917\u094b\u0902 \u0915\u094b \u0905\u0928\u0941\u092e\u0924\u093f \u0926\u0947\u0902", "\u090f\u0915 \u0939\u0940 \u0917\u0924\u093f \u092a\u0930 \u0926\u0930\u094d\u091c \u0915\u0930\u0947\u0902", "\u092a\u094d\u0930\u0935\u0947\u0936 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0909\u0928 \u0932\u094b\u0917\u094b\u0902 \u0915\u094b \u0905\u0928\u0941\u092e\u0924\u093f \u0926\u0947\u0902", "\u0930\u094b\u0915 \u0914\u0930 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor254 = new Task_QueConstructor(266, "\u090f\u0915 \u090f\u092e\u094d\u092c\u0941\u0932\u0947\u0902\u0938 \u092e\u094b\u0939\u093f\u0928\u0940 \u0938\u0941\u0928\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f?", "\u092c\u093e\u0908\u0902 \u0924\u0930\u092b \u091c\u093e\u090f\u0902 \u0914\u0930 \u090f\u092e\u094d\u092c\u0941\u0932\u0947\u0902\u0938 \u0915\u094b \u0930\u093e\u0938\u094d\u0924\u093e \u0926\u0947\u0902", "\u0935\u093e\u0939\u0928 \u0924\u0941\u0930\u0902\u0924 \u092c\u0902\u0926 \u0915\u0930\u094b", "\u092c\u093e\u0908\u0902 \u0924\u0930\u092b \u091c\u093e\u090f\u0902 \u0914\u0930 \u090f\u092e\u094d\u092c\u0941\u0932\u0947\u0902\u0938 \u0915\u094b \u0930\u093e\u0938\u094d\u0924\u093e \u0926\u0947\u0902", "\u090f\u0915 \u0939\u0940 \u0917\u0924\u093f \u092c\u0928\u093e\u090f \u0930\u0916\u0947\u0902", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor255 = new Task_QueConstructor(267, "\u092f\u0926\u093f \u0906\u092a \u091a\u094c\u0930\u093e\u0939\u0947 \u092a\u0930 \u092a\u0940\u0932\u0947 \u0930\u0902\u0917 \u0915\u0940 \u091a\u092e\u0915 \u0915\u094b \u0926\u0947\u0916\u0924\u0947 \u0939\u0948\u0902, \u0924\u094b \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f?", "\u0917\u0924\u093f \u0915\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u0938\u0947 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902", "\u0917\u0924\u093f \u0915\u092e \u0915\u0930\u0947\u0902 \u0914\u0930 \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u0938\u0947 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902", "\u0930\u0941\u0915\u0947\u0902", "\u0927\u094d\u0935\u0928\u093f \u0939\u0949\u0930\u094d\u0928 \u0914\u0930 \u0906\u0917\u0947 \u092c\u0922\u093c\u094b", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor256 = new Task_QueConstructor(268, "\u0915\u0948\u0938\u0947 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u0938\u0902\u0915\u0947\u0924 \u092e\u0947\u0902 \u0930\u094b\u0936\u0928\u0940 \u091a\u092e\u0915 \u0939\u094b\u0917\u093e", "\u0917\u094d\u0930\u0940\u0928, \u092a\u0940\u0932\u093e, \u0930\u0947\u0921, \u0917\u094d\u0930\u0940\u0928", "\u0932\u093e\u0932, \u092a\u0940\u0932\u093e, \u0939\u0930\u093e, \u092a\u0940\u0932\u093e, \u0932\u093e\u0932", "\u0917\u094d\u0930\u0940\u0928, \u092a\u0940\u0932\u093e, \u0930\u0947\u0921, \u0917\u094d\u0930\u0940\u0928", "\u0917\u094d\u0930\u0940\u0928 \u092a\u0940\u0932\u093e \u0930\u0947\u0921 \u092a\u0940\u0932\u093e \u0917\u094d\u0930\u0940\u0928", "nophoto");
            Task_QueConstructor m_rtoTaskQueConstructor257 = new Task_QueConstructor(269, "\u092f\u0926\u093f \u0906\u092a \u0939\u0930\u0947 \u0930\u0902\u0917 \u0915\u0947 \u092c\u093e\u0926 \u092a\u0940\u0932\u0947 \u0930\u0902\u0917 \u0915\u0940 \u0930\u094b\u0936\u0928\u0940 \u0926\u0947\u0916\u0924\u0947 \u0939\u0948\u0902", "\u0915\u0947\u0935\u0932 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902 \u0905\u0917\u0930 '\u0938\u094d\u091f\u0949\u092a \u0932\u093e\u0907\u0928' \u0915\u094b \u092a\u093e\u0930 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948", "\u0924\u0947\u091c \u0914\u0930 \u0932\u093e\u0932 \u0930\u094b\u0936\u0928\u0940 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u094d\u0930\u0949\u0938 \u0915\u0930\u0947\u0902", "\u0915\u0947\u0935\u0932 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902 \u0905\u0917\u0930 '\u0938\u094d\u091f\u0949\u092a \u0932\u093e\u0907\u0928' \u0915\u094b \u092a\u093e\u0930 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948", "\u0905\u0917\u0930 \u0915\u094b\u0908 \u091f\u094d\u0930\u0948\u092b\u093c\u093f\u0915 \u092a\u0941\u0932\u093f\u0938 \u0928\u0939\u0940\u0902 \u0939\u0948 \u0924\u094b \u0930\u094b\u0915\u0947\u0902 \u0914\u0930 \u0906\u0917\u0947 \u092c\u0922\u093c\u0947\u0902", "nophoto");
