            Task_QueConstructor m_rtoTaskQueConstructor268 = new Task_QueConstructor(280, "\u0905\u092a\u0928\u093e \u0935\u093e\u0939\u0928 \u092a\u093e\u0930\u094d\u0915\u093f\u0902\u0917 \u0915\u0947 \u092c\u093e\u0926 \u0906\u092a\u0915\u094b \u0915\u094d\u092f\u093e \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f", "\u0907\u0902\u091c\u0928 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u0915\u0941\u0902\u091c\u0940 \u0928\u093f\u0915\u093e\u0932\u0947\u0902, \u0939\u093e\u0925 \u092c\u094d\u0930\u0947\u0915 \u0932\u093e\u0917\u0942 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0917\u093f\u092f\u0930 \u092e\u0947\u0902 \u0935\u093e\u0939\u0928 \u0921\u093e\u0932\u0947\u0902", "\u0907\u0902\u091c\u0928 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0915\u0941\u0902\u091c\u0940 \u0939\u091f\u093e\u090f\u0902", "\u0907\u0902\u091c\u0928 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u0915\u0941\u0902\u091c\u0940 \u0928\u093f\u0915\u093e\u0932\u0947\u0902 \u0914\u0930 \u0939\u093e\u0925 \u092c\u094d\u0930\u0947\u0915 \u0932\u093e\u0917\u0942 \u0915\u0930\u0947\u0902", "\u0907\u0902\u091c\u0928 \u092c\u0902\u0926 \u0915\u0930\u0947\u0902, \u0915\u0941\u0902\u091c\u0940 \u0928\u093f\u0915\u093e\u0932\u0947\u0902, \u0939\u093e\u0925 \u092c\u094d\u0930\u0947\u0915 \u0932\u093e\u0917\u0942 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0917\u093f\u092f\u0930 \u092e\u0947\u0902 \u0935\u093e\u0939\u0928 \u0921\u093e\u0932\u0947\u0902", "nophoto");
