            Task_QueConstructor m_rtoTaskQueConstructor272 = new Task_QueConstructor(284, "\u0930\u093e\u091c\u094d\u092f \u0914\u0930 \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0940\u092f \u0930\u093e\u091c\u092e\u093e\u0930\u094d\u0917\u094b\u0902 \u092a\u0930 \u090f\u0915 \u0939\u0947\u0932\u092e\u0947\u091f \u092a\u0939\u0928\u0928\u093e", "\u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f", "\u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f", "\u091c\u093c\u0930\u0942\u0930\u0940", "\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915", "nophoto");
