            Task_QueConstructor m_rtoTaskQueConstructor302 = new Task_QueConstructor(314, "\u092f\u0926\u093f 45 \u0915\u093f\u092e\u0940 \u092a\u094d\u0930\u0924\u093f \u0918\u0902\u091f\u0947 \u092a\u0930 \u0917\u093e\u0921\u093c\u0940 \u091a\u0932\u093e \u0930\u0939\u093e \u0939\u0948, \u0924\u094b \u0915\u093e\u0930 \u0938\u0947 \u0906\u0917\u0947 \u0915\u093f\u0924\u0928\u0940 \u0926\u0942\u0930\u0940 \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0939\u0948", "\u0924\u0940\u0928 \u0915\u093e\u0930 \u0915\u0940 \u0932\u0902\u092c\u093e\u0908 \u0907\u0924\u0928\u0940 \u0926\u0942\u0930\u0940", "\u090f\u0915 \u0915\u093e\u0930 \u0915\u0940 \u0932\u0902\u092c\u093e\u0908 \u0907\u0924\u0928\u0940 \u0926\u0942\u0930\u0940", "\u0926\u094b \u0915\u093e\u0930 \u0915\u0940 \u0932\u0902\u092c\u093e\u0908 \u0907\u0924\u0928\u0940 \u0926\u0942\u0930\u0940", "\u0924\u0940\u0928 \u0915\u093e\u0930 \u0915\u0940 \u0932\u0902\u092c\u093e\u0908 \u0907\u0924\u0928\u0940 \u0926\u0942\u0930\u0940", "nophoto");
