            Task_QueConstructor m_rtoTaskQueConstructor305 = new Task_QueConstructor(317, "\u0938\u0921\u093c\u0915 \u0915\u0947 \u0915\u0947\u0902\u0926\u094d\u0930 \u092e\u0947\u0902 \u0932\u0917\u093e\u0924\u093e\u0930 \u090f\u0915 \u092a\u0940\u0932\u0947 \u092a\u091f\u094d\u091f\u0940 \u0907\u0902\u0917\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948?", "\u0913\u0935\u094d\u0939\u0930\u091f\u0947\u0915\u093f\u0902\u0917 \u0928\u093f\u0937\u093f\u0926\u094d\u0927", "\u0906\u0917\u0947 \u092c\u0922\u093c\u0928\u0947 \u0938\u0947 \u092c\u091a\u0947\u0902", "\u0913\u0935\u094d\u0939\u0930\u091f\u0947\u0915\u093f\u0902\u0917 \u0928\u093f\u0937\u093f\u0926\u094d\u0927", "\u0938\u0921\u093c\u0915 \u0915\u093e \u0915\u0947\u0902\u0926\u094d\u0930", "photo");
